/* shared box -------------------------------------------------------------- */
.nav-files-container :is(.nav-file-title, .nav-folder-title):not(:has(> .iconize-icon :is(svg, img)))::before {
  content: "";
  flex: 0 0 var(--plx-ico-size);
  width: var(--plx-ico-size);
  height: var(--plx-ico-size);
  margin: 0 6px 0 var(--plx-ico-lead);
  -webkit-mask: var(--plx-row-key, var(--plx-row-sign, var(--plx-row-icon, var(--plx-ico-file)))) center / var(--plx-ico-size) var(--plx-ico-size) no-repeat;
          mask: var(--plx-row-key, var(--plx-row-sign, var(--plx-row-icon, var(--plx-ico-file)))) center / var(--plx-ico-size) var(--plx-ico-size) no-repeat;
  background-color: var(--plx-row-key-tint, var(--plx-row-tint, var(--plx-tint-file)));
}

/* 3 · type / depth defaults --------------------------------------------- */
.nav-files-container .nav-folder-title {
  --plx-row-icon: var(--plx-ico-folder);
  --plx-row-tint: var(--plx-tint-folder);
}
.nav-files-container .nav-folder-children > .nav-folder:not(.is-collapsed) > .nav-folder-title {
  --plx-row-icon: var(--plx-ico-folder-open);
}
/* top-level folders are the vault's main divisions: a "library" glyph */
.nav-files-container > div > .nav-folder > .nav-folder-title {
  --plx-row-icon: var(--plx-ico-library);
}
.nav-files-container .nav-file-title[data-path$=".md" i]            { --plx-row-icon: var(--plx-ico-file-text); }
.nav-files-container .nav-file-title[data-path$=".canvas" i]        { --plx-row-icon: var(--plx-ico-layout-dashboard); }
.nav-files-container .nav-file-title:is([data-path$=".excalidraw" i],
                                        [data-path$=".excalidraw.md" i]) { --plx-row-icon: var(--plx-ico-pencil-ruler); }
.nav-files-container .nav-file-title[data-path$=".base" i]          { --plx-row-icon: var(--plx-ico-table-2); }
.nav-files-container .nav-file-title[data-path$=".pdf" i]           { --plx-row-icon: var(--plx-ico-file-type); }
.nav-files-container .nav-file-title:is(
    [data-path$=".png" i], [data-path$=".jpg" i], [data-path$=".jpeg" i],
    [data-path$=".gif" i], [data-path$=".svg" i], [data-path$=".webp" i],
    [data-path$=".bmp" i], [data-path$=".avif" i])                  { --plx-row-icon: var(--plx-ico-image); }
.nav-files-container .nav-file-title:is(
    [data-path$=".mp3" i], [data-path$=".wav" i], [data-path$=".m4a" i],
    [data-path$=".ogg" i], [data-path$=".flac" i], [data-path$=".3gp" i]) { --plx-row-icon: var(--plx-ico-file-audio); }
.nav-files-container .nav-file-title:is(
    [data-path$=".mp4" i], [data-path$=".webm" i], [data-path$=".mov" i],
    [data-path$=".mkv" i], [data-path$=".ogv" i])                   { --plx-row-icon: var(--plx-ico-film); }
.nav-files-container .nav-file-title:is(
    [data-path$=".js" i], [data-path$=".mjs" i], [data-path$=".ts" i],
    [data-path$=".py" i], [data-path$=".css" i], [data-path$=".html" i],
    [data-path$=".htm" i], [data-path$=".yml" i], [data-path$=".yaml" i],
    [data-path$=".toml" i], [data-path$=".xml" i], [data-path$=".sh" i],
    [data-path$=".sql" i], [data-path$=".r" i], [data-path$=".jl" i],
    [data-path$=".ipynb" i])                                        { --plx-row-icon: var(--plx-ico-file-code); }
.nav-files-container .nav-file-title[data-path$=".json" i]          { --plx-row-icon: var(--plx-ico-file-json); }
.nav-files-container .nav-file-title:is([data-path$=".csv" i],
                                        [data-path$=".tsv" i])      { --plx-row-icon: var(--plx-ico-sheet); }
.nav-files-container .nav-file-title[data-path$=".tex" i]           { --plx-row-icon: var(--plx-ico-sigma); }
.nav-files-container .nav-file-title[data-path$=".bib" i]           { --plx-row-icon: var(--plx-ico-book-marked); }

/* 2 · prefix signs (own name starts with the sign) ---------------------- */
/* ~ META: cross-cutting / system (Drive "[~] Memos") */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path^="~"], [data-path*="/~"]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path^="~"], [data-path*="/~"]) {
  --plx-row-sign: var(--plx-ico-asterisk);
}
/* _ support / assets */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path^="_"], [data-path*="/_"]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path^="_"], [data-path*="/_"]) {
  --plx-row-sign: var(--plx-ico-paperclip);
}
/* @ people */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path^="@"], [data-path*="/@"]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path^="@"], [data-path*="/@"]) {
  --plx-row-sign: var(--plx-ico-user-round);
}
/* ! pinned / priority */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path^="!"], [data-path*="/!"]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path^="!"], [data-path*="/!"]) {
  --plx-row-sign: var(--plx-ico-pin);
}
/* + inbox / incoming */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path^="+"], [data-path*="/+"]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path^="+"], [data-path*="/+"]) {
  --plx-row-sign: var(--plx-ico-inbox);
}
/* % or = index / map of content */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path^="%"], [data-path*="/%"], [data-path^="="], [data-path*="/="]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path^="%"], [data-path*="/%"], [data-path^="="], [data-path*="/="]) {
  --plx-row-sign: var(--plx-ico-list-tree);
}
/* META rows step back so content folders dominate */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path^="~"], [data-path*="/~"]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path^="~"], [data-path*="/~"]):not(.is-active, :hover) {
  color: var(--plx-ink-3);
  --plx-row-tint: var(--plx-ink-3);
}

/* 1 · keywords in the row's own name (later rules win) ------------------ */
/* Meta */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path$="meta" i]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path$="meta" i]) {
  --plx-row-key: var(--plx-ico-asterisk);
}
/* admin */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path$="admin" i]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path$="admin" i]) {
  --plx-row-key: var(--plx-ico-shield);
}
/* Sandbox */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path*="sandbox" i]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path*="sandbox" i]) {
  --plx-row-key: var(--plx-ico-flask-conical);
}
/* Recent */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path*="recent" i]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path*="recent" i]) {
  --plx-row-key: var(--plx-ico-history);
}
/* Maintenance */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path*="maintenance" i]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path*="maintenance" i]) {
  --plx-row-key: var(--plx-ico-wrench);
}
/* Template(s) */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path*="template" i]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path*="template" i]) {
  --plx-row-key: var(--plx-ico-layout-template);
}
/* Attachment(s) / Assets */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path*="attachment" i], [data-path$="assets" i]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path*="attachment" i], [data-path$="assets" i]) {
  --plx-row-key: var(--plx-ico-paperclip);
}
/* Inbox */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path$="inbox" i]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path$="inbox" i]) {
  --plx-row-key: var(--plx-ico-inbox);
}
/* Archive */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path$="archive" i]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path$="archive" i]) {
  --plx-row-key: var(--plx-ico-archive);
}
/* Sticky Notes */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path*="sticky notes" i]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path*="sticky notes" i]) {
  --plx-row-key: var(--plx-ico-sticky-note);
}
/* Bases */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path$="bases" i]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path$="bases" i]) {
  --plx-row-key: var(--plx-ico-table-2);
}
/* Excalidraw (folder) */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path$="excalidraw" i]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path$="excalidraw" i]) {
  --plx-row-key: var(--plx-ico-pencil-ruler);
}
/* Empty: dashed = absent */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path$="empty" i]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path$="empty" i]) {
  --plx-row-key: var(--plx-ico-circle-dashed);
  --plx-row-key-tint: var(--plx-ink-3);
}
/* Recycle Bin / Trash / Deleted */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path*="recycle bin" i], [data-path$="trash" i], [data-path$="deleted" i]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path*="recycle bin" i], [data-path$="trash" i], [data-path$="deleted" i]) {
  --plx-row-key: var(--plx-ico-trash-2);
  --plx-row-key-tint: var(--plx-ink-3);
}
/* Unfinished / Draft(s) / WIP: amber = provisional */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path*="unfinished" i], [data-path*="draft" i], [data-path$="wip" i], [data-path*="(wip)" i], [data-path*="[wip]" i]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path*="unfinished" i], [data-path*="draft" i], [data-path$="wip" i], [data-path*="(wip)" i], [data-path*="[wip]" i]) {
  --plx-row-key: var(--plx-ico-construction);
  --plx-row-key-tint: var(--plx-amber);
}
/* Low Quality: amber = caution */
:is(.nav-files-container > div,
    .nav-folder:not(:has(> .nav-folder-title:is([data-path*="low quality" i]))) > .nav-folder-children)
  > .tree-item > .tree-item-self:is([data-path*="low quality" i]) {
  --plx-row-key: var(--plx-ico-circle-alert);
  --plx-row-key-tint: var(--plx-amber);
}

/* "you are here": the active row's icon turns teal, whatever it is */
.nav-files-container .tree-item-self.is-active::before {
  background-color: var(--plx-teal) !important;
}

/* Iconize plugin: a user-chosen icon replaces ours; make it match --------
   If Iconize could not resolve its icon (pack not installed) it prints the
   icon NAME as text ("LiMoreVertical"); hide that slot and let our own
   type icon draw. Caveat: Iconize emoji icons are plain text too, so they
   are hidden as well (the vault uses none; revisit if emoji are adopted). */
.nav-files-container .tree-item-self > .iconize-icon:not(:has(svg, img)) {
  display: none;
}
.nav-files-container .tree-item-self > .iconize-icon {
  flex: 0 0 var(--plx-ico-size);
  width: var(--plx-ico-size);
  height: var(--plx-ico-size);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 6px 0 var(--plx-ico-lead) !important;   /* beats Iconize's inline -2px 5px 0 -5px */
  color: var(--plx-ink-2);
  font-size: var(--plx-fs-small);   /* emoji icons */
  line-height: 16px;
  overflow: hidden;
}
.nav-files-container .tree-item-self > .iconize-icon svg {
  width: var(--plx-ico-size);
  height: var(--plx-ico-size);
}
.nav-files-container .tree-item-self.is-active > .iconize-icon {
  color: var(--plx-teal);
}

/* Extension tag for non-markdown files: a tiny mono key-cap ------------- */
:is(.nav-files-container, .workspace-leaf-content[data-type="recent-files"]) .nav-file-tag {
  flex: 0 0 auto;
  order: 8;
  margin: 0 0 0 6px;
  padding: 0 3px;
  height: 14px;
  line-height: 12px;
  box-sizing: border-box;
  font-family: var(--plx-mono);
  font-size: 9.5px;
  font-weight: 400;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: var(--plx-ink-3);
  background: var(--plx-key-face);
  border: 1px solid var(--plx-rule);
  border-radius: 1px;
  box-shadow: inset 0 1px 0 var(--plx-hl);
}
.nav-files-container .tree-item-self.is-active .nav-file-tag {
  color: var(--plx-lcd-ink);
  border-color: var(--plx-teal);
}


/* --------------------------------------------------------------------------
   7. SHARED TREES
   Rows, chevrons, connectors and states above already cover Bookmarks,
   Outline and Tags (same .tree-item DOM). Here: per-pane tick lengths,
   plus the panes whose DOM differs (Recent Files, Search).
   -------------------------------------------------------------------------- */

/* Leaf ticks: Outline and Tags have no icons, so a leaf's tick runs to the
   text (X'+21); Bookmarks draw their own Lucide icon in the chevron slot
   (X'+4…), so the tick stops just before it. */
:is(.workspace-leaf-content[data-type="outline"],
    .workspace-leaf-content[data-type="tag"]) .tree-item-children > .tree-item {
  --plx-c-tick-len: 26px;
}
.workspace-leaf-content[data-type="bookmarks"] .tree-item-children > .tree-item {
  --plx-c-tick-len: 8px;
}
:is(.workspace-leaf-content[data-type="outline"],
    .workspace-leaf-content[data-type="tag"],
    .workspace-leaf-content[data-type="bookmarks"]) .tree-item-children > .tree-item:has(> .tree-item-self .collapse-icon) {
  --plx-c-tick-len: 8px;
}

/* Outline: long headings may wrap; the tick stays on the first line. */
.workspace-leaf-content[data-type="outline"] .tree-item-self {
  align-items: flex-start;
}
.workspace-leaf-content[data-type="outline"] .tree-item-inner {
  white-space: normal;
}

/* Bookmarks: their own type icons, faint, teal when active */
.workspace-leaf-content[data-type="bookmarks"] .tree-item-self > .tree-item-icon:not(.collapse-icon) {
  color: var(--plx-ink-3);
}
.workspace-leaf-content[data-type="bookmarks"] .tree-item-self > .tree-item-icon:not(.collapse-icon) svg {
  width: 14px;
  height: 14px;
}
.workspace-leaf-content[data-type="bookmarks"] .tree-item-self.is-active > .tree-item-icon {
  color: var(--plx-teal);
}

/* Tags: count readout like the folder counters */
.workspace-leaf-content[data-type="tag"] .tree-item-flair {
  font-family: var(--plx-mono);
  font-size: var(--plx-fs-small);
  font-variant-numeric: tabular-nums slashed-zero;
  color: var(--plx-ink-4);
}

/* Recent Files plugin: flat list, same rows + type icons. Its rows carry
   the path in aria-label (not data-path), so icons key off that. */
.workspace-leaf-content[data-type="recent-files"] .nav-folder.mod-root > .nav-folder-children {
  margin: 0;
  padding: 4px 0;
  border: 0;
}
.workspace-leaf-content[data-type="recent-files"] .recent-files-title {
  align-items: center;
  min-height: var(--plx-row);
  margin: 0;
  padding: calc((var(--plx-row) - 16px) / 2) 8px calc((var(--plx-row) - 16px) / 2) 24px;
  line-height: 16px;
  font-family: var(--plx-ui);
  font-size: var(--plx-fs-ui);
  color: var(--plx-ink-2);
  border-radius: 0;
}
.workspace-leaf-content[data-type="recent-files"] .recent-files-title:hover {
  background-color: var(--plx-lcd-2);
  color: var(--plx-ink);
}
.workspace-leaf-content[data-type="recent-files"] .recent-files-title.is-active {
  background-color: var(--plx-lcd);
  background-image:
    linear-gradient(var(--plx-teal), var(--plx-teal)),
    linear-gradient(to bottom left, transparent 50%, var(--plx-teal) 50%);
  background-size: 3px calc(100% - 3px), 3px 3px;
  background-position: left top, left bottom;
  background-repeat: no-repeat;
  color: var(--plx-lcd-ink);
  font-weight: 600;
  --plx-row-tint: var(--plx-teal);
}
.workspace-leaf-content[data-type="recent-files"] .recent-files-title::before {
  content: "";
  flex: 0 0 var(--plx-ico-size);
  width: var(--plx-ico-size);
  height: var(--plx-ico-size);
  margin: 0 6px 0 -5px;
  -webkit-mask: var(--plx-row-icon, var(--plx-ico-file)) center / var(--plx-ico-size) var(--plx-ico-size) no-repeat;
          mask: var(--plx-row-icon, var(--plx-ico-file)) center / var(--plx-ico-size) var(--plx-ico-size) no-repeat;
  background-color: var(--plx-row-tint, var(--plx-tint-file));
}
.recent-files-file[aria-label$=".md" i] > .recent-files-title     { --plx-row-icon: var(--plx-ico-file-text); }
.recent-files-file[aria-label$=".canvas" i] > .recent-files-title { --plx-row-icon: var(--plx-ico-layout-dashboard); }
.recent-files-file:is([aria-label$=".excalidraw" i], [aria-label$=".excalidraw.md" i]) > .recent-files-title { --plx-row-icon: var(--plx-ico-pencil-ruler); }
.recent-files-file[aria-label$=".base" i] > .recent-files-title   { --plx-row-icon: var(--plx-ico-table-2); }
.recent-files-file[aria-label$=".pdf" i] > .recent-files-title    { --plx-row-icon: var(--plx-ico-file-type); }
.recent-files-file:is([aria-label$=".png" i], [aria-label$=".jpg" i], [aria-label$=".jpeg" i],
    [aria-label$=".gif" i], [aria-label$=".svg" i], [aria-label$=".webp" i]) > .recent-files-title { --plx-row-icon: var(--plx-ico-image); }
.workspace-leaf-content[data-type="recent-files"] .nav-file-tag:empty {
  display: none;
}
.workspace-leaf-content[data-type="recent-files"] .recent-files-file-delete {
  display: flex;
  align-items: center;
  color: var(--plx-ink-4);
  opacity: 0;
}
.workspace-leaf-content[data-type="recent-files"] .recent-files-title:hover .recent-files-file-delete {
  opacity: 1;
}
.workspace-leaf-content[data-type="recent-files"] .recent-files-file-delete:hover {
  color: var(--plx-red);     /* destructive: remove from list */
}
.workspace-leaf-content[data-type="recent-files"] .recent-files-file-delete svg {
  width: 12px;
  height: 12px;
}

/* Search results: "[-]"/"[+]" marker (Obsidian's own "\200B" ::before
   would otherwise blank the global marker here) */
.search-result-file-title > .tree-item-icon.collapse-icon::before {
  content: var(--plx-mark-open);
  font-family: var(--plx-mono);
  font-size: 10px;
  line-height: 16px;
  letter-spacing: -0.06em;
  white-space: nowrap;
  color: var(--plx-ink-3);
}
.search-result.is-collapsed > .search-result-file-title > .tree-item-icon.collapse-icon::before,
.search-result-file-title > .tree-item-icon.collapse-icon.is-collapsed::before {
  content: var(--plx-mark-closed);
  color: var(--plx-teal);
}

/* Search results: the file row only (match cards belong to the workspace
   module) — a 24px row with a note icon after the chevron. */
.search-result-file-title {
  align-items: center;
  min-height: var(--plx-row);
  border-radius: 0;
}
.search-result-file-title > .tree-item-inner::before {
  content: "";
  display: inline-block;
  vertical-align: -2px;
  width: 13px;
  height: 13px;
  margin-inline-end: 5px;
  -webkit-mask: var(--plx-ico-file-text) center / 13px 13px no-repeat;
          mask: var(--plx-ico-file-text) center / 13px 13px no-repeat;
  background-color: var(--plx-ink-3);
}
.search-result-file-title:hover {
  background-color: var(--plx-lcd-2);
}


/* --------------------------------------------------------------------------
   8. STYLE SETTINGS TOGGLES
   -------------------------------------------------------------------------- */
body.plx-no-tree-lines .tree-item-children > .tree-item::before,
body.plx-no-tree-lines .tree-item-children > .tree-item::after {
  content: none;
}
body.plx-no-file-icons .nav-files-container .nav-file-title::before,
body.plx-no-file-icons .nav-files-container .nav-folder-title::before,
body.plx-no-file-icons .recent-files-title::before,
body.plx-no-file-icons .search-result-file-title > .tree-item-inner::before {
  content: none;
}


/* ---- a-base/30-reading.css ---- */
/* ==========================================================================
   30 · READING — the paper
   Wiki-style article: Garamond titles with rules, Plex body, dotted
   reference links, wikitable tables, recessed code plates, embeds as
   transclusion panels. Applies to Reading view and Live Preview.
   ========================================================================== */

.markdown-rendered,
.markdown-source-view.mod-cm6 .cm-scroller {
  font-size: var(--font-text-size);
  font-variant-numeric: oldstyle-nums proportional-nums;
  font-kerning: normal;
  text-rendering: optimizeLegibility;
}
.markdown-rendered table, .markdown-rendered code, .markdown-rendered pre { font-variant-numeric: lining-nums tabular-nums; }

/* ---------- Inline title — article title ---------- */
.inline-title {
  font-family: var(--plx-serif);
  font-weight: 500;
  letter-spacing: -0.012em;
  line-height: 1.08;
  margin-bottom: 0.15em !important;
  padding-bottom: 0.28em;
  border-bottom: 1px solid var(--plx-rule);
  position: relative;
}
/* thin second rule under the title: masthead double-rule */
.inline-title::after {
  content: "";
  position: absolute;
  left: 0; right: 0; bottom: -4px;
  border-bottom: 1px solid var(--plx-rule-soft);
}

/* ---------- Headings ---------- */
.markdown-rendered h1, .markdown-rendered h2, .markdown-rendered h3, .markdown-rendered h4,
.HyperMD-header-1, .HyperMD-header-2, .HyperMD-header-3, .HyperMD-header-4 {
  font-feature-settings: "liga", "onum";
  letter-spacing: -0.005em;
}
/* h1, h2 — Wikipedia-style section rules */
.markdown-rendered h1 { border-bottom: 1px solid var(--plx-rule); padding-bottom: 0.12em; margin-top: 1.5em; }
.markdown-rendered h2 { border-bottom: 1px solid var(--plx-rule-soft); padding-bottom: 0.1em; margin-top: 1.4em; }
.cm-line.HyperMD-header-1 { border-bottom: 1px solid var(--plx-rule); padding-bottom: 2px !important; }
.cm-line.HyperMD-header-2 { border-bottom: 1px solid var(--plx-rule-soft); padding-bottom: 2px !important; }
/* h4 — run-in paragraph head feel: Garamond small caps */
.markdown-rendered h4, .cm-header-4 { font-variant: small-caps; letter-spacing: 0.02em; }
/* h5, h6 — instrument labels (condensed caps) */
.markdown-rendered h5, .markdown-rendered h6, .cm-header-5, .cm-header-6 {
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.markdown-rendered h5 { margin-bottom: 0.2em; }
/* § mark on hover — section anchor */
.markdown-rendered :is(h1, h2, h3):hover::after {
  content: none;
  color: var(--plx-ink-4);
  font-weight: 400;
  font-size: 0.7em;
}
.markdown-rendered :is(h1,h2,h3,h4,h5,h6) .heading-collapse-indicator { color: var(--plx-ink-4); }

/* ---------- Paragraph texture ---------- */
.markdown-rendered p, .markdown-rendered li { hyphens: auto; }
.markdown-rendered strong, .cm-strong { color: var(--plx-ink); font-weight: 600; }
.markdown-rendered em, .cm-em { font-family: inherit; }
mark, .markdown-rendered mark, .cm-highlight {
  background: var(--text-highlight-bg);
  color: inherit;
  border-radius: 0;
  padding: 0 1px;
  box-shadow: inset 0 -0.15em 0 rgba(170, 140, 30, 0.25);
}
del, .cm-strikethrough { text-decoration-color: var(--plx-red); text-decoration-thickness: 1px; color: var(--plx-ink-3); }
sub, sup { font-size: 0.72em; }

/* ---------- Links — semiotics: dotted = pointer, dashed red = not yet existing ---------- */
.markdown-rendered a.internal-link,
.cm-hmd-internal-link .cm-underline,
.cm-s-obsidian span.cm-hmd-internal-link {
  color: var(--plx-teal);
  text-decoration-line: underline;
  text-decoration-style: dotted;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  text-decoration-color: color-mix(in srgb, var(--plx-teal) 60%, transparent);
}
.markdown-rendered a.internal-link:hover,
.cm-hmd-internal-link .cm-underline:hover {
  color: var(--plx-teal-bright);
  text-decoration-style: solid;
  background: var(--plx-teal-wash);
}
.markdown-rendered a.internal-link.is-unresolved,
.cm-hmd-internal-link.is-unresolved .cm-underline,
.is-unresolved {
  color: var(--plx-red);
  opacity: 1;
  text-decoration-style: dashed;
  text-decoration-color: color-mix(in srgb, var(--plx-red) 55%, transparent);
}
.markdown-rendered a.external-link,
.cm-link .cm-underline, .cm-url {
  color: var(--plx-teal);
  text-decoration-line: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  text-decoration-color: color-mix(in srgb, var(--plx-teal) 45%, transparent);
}
/* external link mark: a small ↗ instead of Obsidian's icon */
.markdown-rendered a.external-link {
  background-image: none !important;
  padding-inline-end: 0;
}
.markdown-rendered a.external-link::after {
  content: "↗";
  font-family: var(--plx-ui);
  font-size: 0.7em;
  vertical-align: 0.35em;
  margin-inline-start: 1px;
  color: var(--plx-ink-3);
  text-decoration: none;
  display: inline-block;
}
.markdown-rendered a.external-link:hover { background: var(--plx-teal-wash); }

/* ---------- Tags — key-cap labels ---------- */
a.tag, .cm-hashtag {
  font-family: var(--plx-mono);
  font-size: 0.76em;
  letter-spacing: 0;
  border: 1px solid var(--plx-rule);
  border-radius: 1px;
  background: var(--plx-paper-2);
  color: var(--plx-ink-2);
  padding: 0 0.42em;
  text-decoration: none;
  vertical-align: 0.08em;
}
.cm-hashtag-begin { border-inline-end: none; padding-inline-end: 0; border-radius: 1px 0 0 1px; }
.cm-hashtag-end { border-inline-start: none; padding-inline-start: 0; border-radius: 0 1px 1px 0; }
a.tag:hover { border-color: var(--plx-teal); color: var(--plx-teal); background: var(--plx-teal-wash); }

/* ---------- Lists, tasks ---------- */
.markdown-rendered ul > li::marker { color: var(--plx-ink-3); }
.markdown-rendered ol > li::marker { color: var(--plx-ink-3); font-family: var(--plx-ui); font-size: 0.9em; font-variant-numeric: tabular-nums; }
/* square bullets — instrument, not soft */
.list-bullet::after { border-radius: 0 !important; width: 5px; height: 5px; background-color: var(--plx-ink-3); }
.markdown-rendered ul ul .list-bullet::after, .cm-formatting-list-ul + * .list-bullet::after { background: transparent; border: 1px solid var(--plx-ink-3); width: 4px; height: 4px; }
.markdown-rendered ul > li > .list-bullet { }
/* indentation guides in lists */
.markdown-rendered.show-indentation-guide li > ul::before,
.markdown-rendered.show-indentation-guide li > ol::before { border-inline-end: 1px solid var(--plx-rule-soft); }

/* checkboxes: □ open / ■ done (semiotic standard) */
input[type="checkbox"], .task-list-item-checkbox {
  border-radius: 1px !important;
  border: 1px solid var(--plx-rule-strong);
  background: var(--plx-well);
  box-shadow: var(--plx-recessed);
  width: 13px; height: 13px;
}
input[type="checkbox"]:checked {
  background-color: var(--plx-teal);
  border-color: color-mix(in srgb, var(--plx-teal) 60%, black);
  box-shadow: none;
}
.markdown-rendered li[data-task="-"], .HyperMD-task-line[data-task="-"] { color: var(--plx-ink-3); text-decoration: line-through; text-decoration-color: var(--plx-ink-4); }
.markdown-rendered li[data-task="-"] > input, .HyperMD-task-line[data-task="-"] input { background-image: var(--plx-hatch); }

/* ---------- Tables — wikitable ---------- */
.markdown-rendered table {
  border-collapse: collapse;
  border: 1px solid var(--plx-rule-strong);
  background: var(--plx-paper);
  font-size: 0.92em;
  margin: 1em 0;
  min-width: 40%;
}
.markdown-rendered th, .markdown-rendered td {
  border: 1px solid var(--plx-rule);
  padding: 4px 9px;
  line-height: 1.4;
}
.markdown-rendered thead th, .markdown-rendered th {
  background: var(--plx-paper-2);
  font-family: var(--plx-ui-cond);
  font-size: 0.82em;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--plx-ink);
  border-bottom: 2px solid var(--plx-rule-strong);
}
.markdown-rendered tbody tr:hover { background: var(--plx-teal-wash); }
.markdown-rendered td[align="right"], .markdown-rendered td[style*="right"] { font-family: var(--plx-mono); font-size: 0.92em; }
/* Live Preview table widget */
.cm-table-widget table { border: 1px solid var(--plx-rule-strong); }
.cm-table-widget th { font-family: var(--plx-ui-cond); text-transform: uppercase; letter-spacing: 0.05em; font-size: 0.82em; background: var(--plx-paper-2); }

/* ---------- Code — a recessed display plate with a label ---------- */
.markdown-rendered pre,
.HyperMD-codeblock {
  background: var(--plx-paper-2) !important;
}
.markdown-rendered pre {
  border: 1px solid var(--plx-rule);
  border-top: 1px solid var(--plx-rule-strong);
  border-radius: var(--plx-r);
  box-shadow: var(--plx-recessed);
  padding: 1.6em 1em 0.8em;
  position: relative;
  font-size: 0.86em;
  line-height: 1.55;
}
/* language label, top-left, like a panel legend */
.markdown-rendered pre[class*="language-"]::before {
  content: "code";
  position: absolute; top: 0; left: 0;
  padding: 1px 8px;
  font-family: var(--plx-ui-cond);
  font-size: 9.5px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--plx-slate-ink);
  background: var(--plx-slate-2);
  padding-inline-end: 14px;
  border-radius: var(--plx-r) 0 0 0;
  clip-path: var(--plx-clip-br);
}
.markdown-rendered pre.language-python::before { content: "python"; }
.markdown-rendered pre.language-js::before, .markdown-rendered pre.language-javascript::before { content: "javascript"; }
.markdown-rendered pre.language-ts::before, .markdown-rendered pre.language-typescript::before { content: "typescript"; }
.markdown-rendered pre.language-bash::before, .markdown-rendered pre.language-sh::before, .markdown-rendered pre.language-shell::before { content: "shell"; }
.markdown-rendered pre.language-css::before { content: "css"; }
.markdown-rendered pre.language-json::before { content: "json"; }
.markdown-rendered pre.language-latex::before, .markdown-rendered pre.language-tex::before { content: "tex"; }
.markdown-rendered pre.language-r::before { content: "r"; }
.markdown-rendered pre.language-julia::before { content: "julia"; }
.markdown-rendered pre.language-cpp::before, .markdown-rendered pre.language-c::before { content: "c / c++"; }
.markdown-rendered pre.language-rust::before { content: "rust"; }
.markdown-rendered pre.language-yaml::before, .markdown-rendered pre.language-yml::before { content: "yaml"; }
.markdown-rendered pre.language-md::before, .markdown-rendered pre.language-markdown::before { content: "markdown"; }
.markdown-rendered pre.language-html::before { content: "html"; }
.markdown-rendered pre.language-sql::before { content: "sql"; }
.markdown-rendered pre:not([class*="language-"]) { padding-top: 0.8em; }
.markdown-rendered pre .copy-code-button {
  font-family: var(--plx-ui-cond); font-size: 10px; text-transform: uppercase; letter-spacing: 0.06em;
  background: var(--plx-key-face); border: 1px solid var(--plx-rule); border-radius: 2px; box-shadow: var(--plx-raised);
  color: var(--plx-ink-2); padding: 1px 6px; margin: 4px; top: 0;
}
.markdown-rendered pre .copy-code-button:hover { color: var(--plx-teal); }
/* Live preview code block: bracket lines as plate edges */
.HyperMD-codeblock-begin { border-top: 1px solid var(--plx-rule-strong); border-radius: 0 !important; }
.HyperMD-codeblock-end { border-bottom: 1px solid var(--plx-rule); border-radius: 0 !important; }
.HyperMD-codeblock { border-inline: 1px solid var(--plx-rule-soft); }
.cm-s-obsidian .HyperMD-codeblock .code-block-flair { font-family: var(--plx-ui-cond); text-transform: uppercase; letter-spacing: 0.08em; font-size: 10px; color: var(--plx-ink-3); }

/* inline code */
.markdown-rendered :not(pre) > code,
.cm-s-obsidian span.cm-inline-code {
  font-family: var(--plx-mono);
  font-size: 0.84em;
  background: var(--plx-paper-2);
  border: 1px solid var(--plx-rule-soft);
  border-radius: 1px;
  padding: 0.05em 0.3em;
  color: var(--plx-ink);
}

/* ---------- Blockquote — quotation, Garamond ---------- */
.markdown-rendered blockquote {
  font-family: var(--plx-serif);
  font-size: 1.12em;
  font-style: italic;
  line-height: 1.5;
  color: var(--plx-ink-2);
  border-inline-start: 2px solid var(--plx-rule-strong);
  padding: 0.1em 0 0.1em 1.1em;
  margin: 1.2em 1.5em 1.2em 0.4em;
}
.HyperMD-quote { font-family: var(--plx-serif); font-size: 1.08em; font-style: italic; color: var(--plx-ink-2); }
.HyperMD-quote::before { border-inline-start: 2px solid var(--plx-rule-strong) !important; }

/* ---------- Horizontal rule — a centred three-dot fleuron ---------- */
.markdown-rendered hr {
  border: none;
  border-top: 1px solid var(--plx-rule);
  height: 0;
  margin: 2em 0;
  overflow: visible;
  text-align: center;
}
.markdown-rendered hr::after {
  content: "◆";
  position: relative; top: -0.72em;
  padding: 0 0.6em;
  background: var(--plx-paper);
  color: var(--plx-ink-4);
  font-size: 0.75em;
}
.hr .cm-line hr, .markdown-source-view .hr hr { border-top: 1px solid var(--plx-rule); }

/* ---------- Footnotes & references ---------- */
.markdown-rendered sup.footnote-ref, .footnote-link, .cm-footref {
  font-family: var(--plx-ui);
  font-size: 0.7em;
}
.markdown-rendered .footnote-link, .markdown-rendered sup a {
  color: var(--plx-teal);
  text-decoration: none;
}
.markdown-rendered sup.footnote-ref a::before { content: "["; color: var(--plx-ink-4); }
.markdown-rendered sup.footnote-ref a::after { content: "]"; color: var(--plx-ink-4); }
.markdown-rendered section.footnotes {
  border-top: 1px solid var(--plx-rule);
  margin-top: 2.5em;
  padding-top: 0.6em;
  font-size: 0.86em;
  color: var(--plx-ink-2);
}
.markdown-rendered section.footnotes::before {
  content: "References";
  display: block;
  font-family: var(--plx-serif);
  font-size: 1.35em;
  color: var(--plx-ink);
  margin-bottom: 0.3em;
}
.markdown-rendered .footnotes hr { display: none; }
.markdown-rendered .footnotes ol li::marker { font-family: var(--plx-mono); color: var(--plx-ink-3); }
.footnote-backref { color: var(--plx-teal); }

/* ---------- Embeds / transclusions — a panel with a label strip ---------- */
.markdown-embed {
  border: 1px solid var(--plx-rule);
  border-inline-start: 3px solid var(--plx-teal);
  border-radius: 0;
  background: var(--plx-paper);
  padding: 0;
  margin: 1em 0;
}
.markdown-embed .markdown-embed-content { padding: 0.2em 1.1em 0.6em; max-height: 32em; }
.markdown-embed .markdown-preview-view { padding: 0; }
.markdown-embed-title {
  display: inline-block !important;
  width: auto !important;
  height: auto;
  padding: 2px 16px 2px 10px;
  margin: 0;
  clip-path: var(--plx-clip-br);
  font-family: var(--plx-ui-cond);
  font-size: var(--plx-fs-label);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--plx-track);
  color: var(--plx-ink-2);
  background: var(--plx-case-hi);
  border-bottom: 1px solid var(--plx-rule-soft);
  text-align: start;
}
.markdown-embed .inline-title { font-size: 1.6em; border: none; }
.markdown-embed .inline-title::after { display: none; }
.markdown-embed-link { color: var(--plx-ink-3); top: 0; padding: 2px; }
.markdown-embed-link:hover { color: var(--plx-teal); }
.internal-embed.file-embed { border: 1px solid var(--plx-rule); border-radius: 0; background: var(--plx-paper-2); }
/* image embeds: plate with hairline */
.markdown-rendered img:not([width]), .image-embed img { border: 1px solid var(--plx-rule-soft); }
.image-embed[alt]:not([alt$=".png"]):not([alt$=".jpg"]):not([alt$=".jpeg"]):not([alt$=".gif"]):not([alt$=".svg"]):not([alt$=".webp"])::after {
  content: attr(alt);
  display: block;
  font-family: var(--plx-ui);
  font-size: 0.82em;
  color: var(--plx-ink-2);
  padding: 3px 0 0;
  border-top: 1px solid var(--plx-rule-soft);
}

/* ---------- Math ---------- */
.math-block, mjx-container[display="true"] { margin: 1.1em 0; }
mjx-container { color: var(--plx-ink); }
.markdown-rendered .math-block { padding: 0.3em 0; }

/* ---------- Mermaid / diagrams in instrument palette ---------- */
.markdown-rendered .mermaid { font-family: var(--plx-ui) !important; }
.mermaid .node rect, .mermaid .node polygon, .mermaid .node circle, .mermaid .node path {
  fill: var(--plx-paper-2) !important; stroke: var(--plx-rule-strong) !important; stroke-width: 1px !important;
}
.mermaid .edgePath .path, .mermaid .flowchart-link { stroke: var(--plx-ink-2) !important; stroke-width: 1px !important; }
.mermaid .arrowheadPath, .mermaid marker path { fill: var(--plx-ink-2) !important; stroke: none !important; }
.mermaid .edgeLabel, .mermaid .edgeLabel rect, .mermaid .labelBkg { background: var(--plx-paper) !important; fill: var(--plx-paper) !important; color: var(--plx-ink-2) !important; }
.mermaid .nodeLabel, .mermaid .label { color: var(--plx-ink) !important; font-family: var(--plx-ui) !important; }

/* ---------- Source mode / editor niceties ---------- */
.cm-s-obsidian .cm-formatting, .cm-formatting-header { color: var(--plx-ink-4) !important; }
.markdown-source-view.mod-cm6 .cm-gutters { background: transparent; border-inline-end: 1px solid var(--plx-rule-soft); }
.cm-lineNumbers .cm-gutterElement { font-family: var(--plx-mono); font-size: 10.5px; color: var(--plx-ink-4); }
.cm-active.cm-line { background: transparent; }
.markdown-source-view.mod-cm6 .cm-cursor { border-left: 2px solid var(--plx-teal); }
.cm-fold-indicator .collapse-indicator { color: var(--plx-ink-4); }
.markdown-source-view.mod-cm6 .cm-embed-block:not(.cm-table-widget):hover { box-shadow: 0 0 0 1px var(--plx-rule) !important; border-radius: 0 !important; }
.edit-block-button { border-radius: 2px; }

/* print / PDF: paper only */
@media print {
  .inline-title::after { display: none; }
  .markdown-rendered { font-family: var(--plx-text-serif); }
}

/* cancelled task [-]: hatched box with a dash, not a teal check (semiotic: hatched = absent) */
.markdown-rendered li[data-task="-"] > input[type="checkbox"],
.markdown-rendered li[data-task="-"] > p > input[type="checkbox"],
.HyperMD-task-line[data-task="-"] input[type="checkbox"] {
  background-color: var(--plx-paper-2) !important;
  background-image: var(--plx-hatch) !important;
  border-color: var(--plx-ink-4) !important;
}
.markdown-rendered li[data-task="-"] input[type="checkbox"]::after,
.HyperMD-task-line[data-task="-"] input[type="checkbox"]::after {
  -webkit-mask-image: none !important;
  background: var(--plx-ink-3) !important;
  width: 7px !important; height: 1.5px !important;
  inset: 0 !important; margin: auto !important;
  position: absolute; content: "";
}

/* Table type scale: header caps sized so their cap height matches the cells' cap height */
.markdown-rendered table, .cm-table-widget table { font-size: 0.88em; }            /* ≈ 13.2px cells */
.markdown-rendered th, .markdown-rendered thead th,
.cm-table-widget th {
  font-size: 0.94em !important;                                                    /* ≈ 12.4px caps */
  letter-spacing: 0.04em;
  line-height: 1.3;
  vertical-align: bottom;
}
.markdown-rendered td, .cm-table-widget td { line-height: 1.45; vertical-align: baseline; }
.markdown-rendered td[align="right"], .markdown-rendered td[style*="right"] { font-size: 0.95em; }

.markdown-rendered pre.language-text::before, .markdown-rendered pre.language-txt::before, .markdown-rendered pre.language-plain::before { content: "text"; }
.markdown-rendered pre.language-mermaid::before { content: "mermaid"; }
.markdown-rendered pre.language-base::before { content: "base"; }
.markdown-rendered pre.language-dataview::before { content: "dataview"; }
.markdown-rendered pre.language-ts::before { content: "typescript"; }
/* headings next to a floated infobox: rule stops at the float (Wikipedia behaviour) */
.markdown-rendered :is(h1, h2) { display: flow-root; }
/* math sits in the CMU text face family: slightly larger display maths */
.markdown-rendered mjx-container[display="true"] { font-size: 1.04em; }

/* ---------- Relative sizes: one x-height for every reading face ----------
   The Font size slider sets the base; font-size-adjust then scales each face
   so its lowercase is 0.5 of that size — CMU Serif, Plex, Georgia … read alike.
   Headings, code and maths keep their own designed proportions. */
.markdown-preview-view, .markdown-source-view.mod-cm6 .cm-content { font-size-adjust: 0.5; line-height: 1.62; }
.markdown-rendered :is(h1, h2, h3, h4, h5, h6), .inline-title, .cm-line:is(.HyperMD-header-1, .HyperMD-header-2, .HyperMD-header-3, .HyperMD-header-4, .HyperMD-header-5, .HyperMD-header-6),
.markdown-rendered :is(code, pre, kbd), .cm-inline-code, .HyperMD-codeblock, mjx-container, .math, .callout-title,
.metadata-container, a.tag, .cm-hashtag, .markdown-rendered th { font-size-adjust: none; }
/* comfortable paragraph rhythm */
.markdown-rendered p { margin-block: 0 0.85em; }
.markdown-rendered li { margin-block: 0.12em; }

/* Quotations — readable: reading face upright, a hair larger; one Garamond mark */
.markdown-rendered blockquote {
  font-family: var(--plx-quote-font);
  font-style: var(--plx-quote-style);
  font-size: 1.03em;
  line-height: 1.6;
  color: var(--plx-ink-2);
  position: relative;
  padding-inline-start: 1.7em;
}
.markdown-rendered blockquote::before {
  content: "“";
  position: absolute;
  left: 0.35em; top: 0.02em;
  font-family: var(--plx-serif);
  font-size: 1.9em;
  line-height: 1;
  color: var(--plx-ink-4);
}
.markdown-rendered blockquote em, .markdown-rendered blockquote i { font-style: italic; }
.HyperMD-quote { font-family: var(--plx-quote-font) !important; font-style: var(--plx-quote-style) !important; font-size: 1.03em !important; }


/* ---- a-base/35-tags.css ---- */
/* ==========================================================================
   35 · TYPED TAGS — base look. Families: b-layer/84-tag-options.css
   Families differ ONLY by colour (same shape, border, weight and contrast):
     TOPIC   teal        #information-theory
     TYPE    blue-violet #type/article
     STATUS  amber       #status/draft
     STABLE  green       #status/stable
     ABSENT  rose        #status/empty, #status/trash
     META    slate gray  #meta/...
   Each hue is chosen at matched lightness so no family reads louder.
   Tags in the Properties box are coloured by the Typed Pages plugin.
   ========================================================================== */

.theme-light {
  --plx-tagc-topic:  #1f6f6a;
  --plx-tagc-form:   #4f5aa0;
  --plx-tagc-status: #8a6414;
  --plx-tagc-stable: #3a7348;
  --plx-tagc-absent: #9a4b5a;
  --plx-tagc-meta:   #5c6670;
}
.theme-dark {
  --plx-tagc-topic:  #6cc3bb;
  --plx-tagc-form:   #a3acf0;
  --plx-tagc-status: #e6b25e;
  --plx-tagc-stable: #8fcb9c;
  --plx-tagc-absent: #ea98a7;
  --plx-tagc-meta:   #aeb6be;
}
body { --plx-tag-h: var(--plx-tagc-topic); }
body:not(.plx-tags-plain) a.tag,
body:not(.plx-tags-plain) .cm-hashtag {
  color: var(--plx-tag-h);
  background: color-mix(in srgb, var(--plx-tag-h) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--plx-tag-h) 42%, transparent);
  border-radius: 2px;
  font-family: var(--plx-mono);
  font-weight: 400;
  text-transform: none;
  letter-spacing: 0;
  text-decoration: none;
}
body:not(.plx-tags-plain) a.tag:hover { background: color-mix(in srgb, var(--plx-tag-h) 18%, transparent); }
/* live preview splits a tag into "#" + name: keep the seam invisible */
body:not(.plx-tags-plain) .cm-hashtag-begin { border-inline-end: none; border-radius: 2px 0 0 2px; }
body:not(.plx-tags-plain) .cm-hashtag-end { border-inline-start: none; border-radius: 0 2px 2px 0; }
/* The family rules (type/, status/, meta/, author/) are in b-layer/84-tag-options.css. */


/* ---- a-base/40-callouts.css ---- */
/* ==========================================================================
   40 · CALLOUTS
   Instrument plates, typeset formal objects, lab-paper elements, wiki parts.
   Uses only --plx-* tokens (00-tokens.css) and Obsidian variables.

   ── HOW TO WRITE THEM ────────────────────────────────────────────────────
   Standard plates   > [!note] / info / tip / success / question / warning /
                     failure / danger / bug / example / quote / abstract / todo
                     (+ Obsidian's aliases). Title = condensed-caps label.

   Formal objects    > [!theorem] Cauchy–Schwarz      →  [THEOREM 03] Cauchy–Schwarz
   (amsthm family)   > [!thm]                         →  [THEOREM 03]
                     > [!theorem|anon]                →  [THEOREM 03]
                     > [!theorem|star] Zorn           →  [THEOREM] Zorn   (theorem*)
     CONVENTION: CSS cannot tell Obsidian's default title ("Theorem") from a
     typed one, so: the LONG type name shows the title text as the object's
     name; the SHORT alias (thm, lem, prop, cor, defn, def, rmk, rem, obs, conj,
     clm, ax, post, exr, prob, nota, pf, sol, hyp, asm) never shows title text. Use the alias (or |anon) for
     an unnamed object, the long name when you give it a name.

   Numbering         One shared counter for the whole theorem family (like
                     amsthm [theorem]); separate counters for hypothesis H.01,
                     assumption A.01, equation (01), figure, table, algorithm.
                     Scope = one note (.markdown-preview-view / LP scroller).
                     Embeds and hover previews number on their own.
     LIMITS: Reading view is exact. Live Preview (CodeMirror) only keeps the
     lines near the viewport in the DOM, so in long notes LP numbers count
     from the first rendered callout and can be low; in LP the proven-object
     tab is drawn tinted, not filled, to say "provisional". Reading view /
     PDF are authoritative.

   Metadata flags    > [!type|flag flag]  (space- or pipe-separated)
                     star | nonum   unnumbered, does not advance the counter
                     anon           hide the title text (label only)
                     upright        upright body for a plain-style theorem
                     italic         italic body for a definition-style one
                     titled         show the title on an equation (as a tag)
                     left | nofloat infobox: float left / don't float
                     wide           table/infobox: full line width

   Wiki hatnotes     > [!seealso]  / [!main] / [!further] : text goes in the
                     BODY (title is replaced by "See also:"), or a title-only
                     callout `> [!seealso] [[Page]]` uses the title as text.
   ========================================================================== */


/* --------------------------------------------------------------------------
   0 · COUNTER SCOPE — one numbering per rendered note
   -------------------------------------------------------------------------- */
.markdown-preview-view,
.markdown-source-view.mod-cm6 .cm-scroller {
  counter-reset: plx-thm plx-hyp plx-asm plx-eq plx-fig plx-tab plx-alg;
}

/* Note pane is a size container so the infobox can stop floating in narrow
   panes. (container-type also scopes counters to the pane — harmless.) */
.workspace-leaf-content[data-type="markdown"] > .view-content {
  container: plx-note / inline-size;
}


/* --------------------------------------------------------------------------
   1 · BASE PLATE — every callout starts as an instrument plate
   -------------------------------------------------------------------------- */
.callout {
  /* per-type hooks (overridden below) */
  --plx-co: var(--plx-steel);
  --plx-co-wash: var(--plx-steel-wash);
  --plx-co-line: solid;
  --plx-co-edge: color-mix(in srgb, var(--plx-co) 38%, var(--plx-rule));
  --plx-co-ink: color-mix(in srgb, var(--plx-co) 78%, var(--plx-ink));
  /* numbering hooks: no counter unless a type sets one */
  --plx-ctr: none;
  --plx-num: "";
  --plx-label: "";
  counter-increment: var(--plx-ctr);

  position: relative;
  margin: 1em 0;
  padding: 0;
  overflow: hidden;
  background: var(--plx-plate);
  border: 1px var(--plx-co-line) var(--plx-co-edge);
  border-radius: var(--plx-r);
  mix-blend-mode: normal;
  box-shadow: 0 1px 0 color-mix(in srgb, var(--plx-co) 10%, transparent);
}

.callout > .callout-title {
  align-items: center;
  gap: 7px;
  min-height: 24px;
  padding: 3px 10px 3px 4px;
  background:
    linear-gradient(var(--plx-co-wash), var(--plx-co-wash)),
    var(--plx-paper-2);
  box-shadow: inset 0 1px 0 var(--plx-hl);
  border-bottom: 1px solid color-mix(in srgb, var(--plx-co) 22%, var(--plx-rule-soft));
  color: var(--plx-co-ink);
  font-family: var(--plx-ui-cond);
  font-size: 11px;
  font-weight: 700;
  line-height: 1.3;
  letter-spacing: var(--plx-track);
  text-transform: uppercase;
  /* Univers Condensed's kern table collapses word spaces after caps (S␣, E␣
     → 1px). Kerning off keeps "IS THE" from reading "ISTHE". */
  font-kerning: none;
}
.callout.is-collapsed > .callout-title { border-bottom-color: transparent; }
.callout > .callout-title .callout-title-inner {
  font-weight: inherit;
  color: inherit;
}
/* math, code and links inside titles keep their own case/tracking */
.callout-title :is(mjx-container, .math, code, .katex) {
  text-transform: none;
  letter-spacing: normal;
}

/* Icon = a small filled key chip in the type colour, chamfered bottom-right */
.callout > .callout-title > .callout-icon {
  flex: 0 0 auto;
  width: 19px;
  height: 17px;
  align-items: center;
  justify-content: center;
  background: var(--plx-co);
  color: var(--plx-paper);
  clip-path: var(--plx-clip-br);
}
.callout > .callout-title > .callout-icon::after { content: none; }
.callout > .callout-title > .callout-icon .svg-icon {
  width: 11px;
  height: 11px;
  color: var(--plx-paper);
  stroke-width: 2.2px;
}

/* Fold chevron ▸ */
.callout-title > .callout-fold {
  margin-left: auto;
  padding: 0 0 0 4px;
  color: var(--plx-ink-3);
}
.callout-title > .callout-fold .svg-icon { width: 12px; height: 12px; stroke-width: 2px; }
.callout.is-collapsible > .callout-title { cursor: pointer; }
.callout.is-collapsible > .callout-title:hover .callout-fold { color: var(--plx-teal); }

.callout > .callout-content {
  padding: 7px 12px 9px;
  background: transparent;
  overflow-x: auto;
  overflow-y: hidden; /* x:auto alone also spawns a y scrollbar on glyph overhang */
}
.callout > .callout-content > :first-child { margin-top: 0; }
.callout > .callout-content > :last-child { margin-bottom: 0; }

/* Nested callouts and callouts inside embeds sit tighter */
.callout .callout { margin: 0.6em 0; }
.callout .callout:last-child { margin-bottom: 0.2em; }
.markdown-embed .callout { margin: 0.6em 0; }

/* Live Preview wrapper: no extra frame around the plate */
.markdown-source-view.mod-cm6 .cm-embed-block.cm-callout {
  background: transparent;
  box-shadow: none;
}
.markdown-source-view.mod-cm6 .cm-embed-block.cm-callout > .callout { margin: 0.35em 0; }


/* Dark-mode tunings for filled shapes (slate is near-black at night) */
body { --plx-captab-bg: var(--plx-slate-2); --plx-captab-ink: var(--plx-slate-ink); }
.theme-dark { --plx-captab-bg: var(--plx-ink-2); --plx-captab-ink: var(--plx-paper); }

/* --------------------------------------------------------------------------
   2 · COPY BUTTONS (callout-copy-buttons plugin) — tiny Casio keys
   The plugin uses !important on background/box-shadow; we must match it.
   -------------------------------------------------------------------------- */
.callout > .callout-action-buttons {
  top: 4px;
  inset-inline-end: 6px;
  gap: 3px;
  z-index: 2;
}
.callout.is-collapsible > .callout-action-buttons { inset-inline-end: 26px; }
.callout > .callout-action-buttons .callout-copy-button,
.callout > .callout-action-buttons .edit-block-button {
  width: 20px;
  height: 16px;
  padding: 0;
  align-items: center;
  justify-content: center;
  background: var(--plx-key-face) !important;
  border: 1px solid var(--plx-rule);
  border-radius: 2px;
  box-shadow: var(--plx-raised) !important;
  color: var(--plx-ink-2);
  font-family: var(--plx-mono);
  font-size: 8px;
  opacity: 0;
  transition: opacity 120ms;
}
.callout > .callout-action-buttons .callout-copy-button svg,
.callout > .callout-action-buttons .edit-block-button svg {
  width: 10px;
  height: 10px;
  stroke-width: 2px;
}
.callout:hover > .callout-action-buttons .callout-copy-button,
.callout:hover > .callout-action-buttons .edit-block-button,
.cm-callout:hover .callout > .callout-action-buttons .callout-copy-button { opacity: 0.9; }
.callout > .callout-action-buttons .callout-copy-button:hover {
  background: var(--plx-key-face) !important;
  border-color: var(--plx-rule-strong);
  color: var(--plx-ink);
  opacity: 1;
}
.callout > .callout-action-buttons .callout-copy-button:active {
  background: var(--plx-key-face-down) !important;
  box-shadow: var(--plx-pressed) !important;
}
.callout > .callout-action-buttons .callout-copy-button.just-copied {
  color: var(--plx-green);
  border-color: var(--plx-green);
}
/* M / P format letters: mono, tucked bottom-right like a key legend */
.callout > .callout-action-buttons .callout-copy-button::after {
  font-family: var(--plx-mono);
  font-weight: 700;
  font-size: 7px;
  top: auto;
  bottom: -1px;
  left: auto;
  right: 1px;
  transform: none;
}


/* Live Preview: Obsidian's own "edit block" button sits in .embed-actions at
   the top-right of the .cm-callout. Make it the rightmost key of the row and
   shift the copy keys left of it. */
.markdown-source-view.mod-cm6 .cm-callout > .embed-actions {
  top: 6px;
  inset-inline-end: 6px;
  z-index: 3;
}
.markdown-source-view.mod-cm6 .cm-callout > .embed-actions .edit-block-button {
  width: 20px;
  height: 16px;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--plx-key-face);
  border: 1px solid var(--plx-rule);
  border-radius: 2px;
  box-shadow: var(--plx-raised);
  color: var(--plx-ink-2);
}
.markdown-source-view.mod-cm6 .cm-callout > .embed-actions .edit-block-button svg { width: 10px; height: 10px; stroke-width: 2px; }
.markdown-source-view.mod-cm6 .cm-callout > .embed-actions .edit-block-button:active {
  background: var(--plx-key-face-down);
  box-shadow: var(--plx-pressed);
}
.markdown-source-view.mod-cm6 .cm-callout > .markdown-rendered > .callout > .callout-action-buttons {
  top: 5px;
  inset-inline-end: 29px;
}
.markdown-source-view.mod-cm6 .cm-callout > .markdown-rendered > .callout.is-collapsible > .callout-action-buttons {
  inset-inline-end: 49px;
}

/* --------------------------------------------------------------------------
   3 · STANDARD TYPES — colour = meaning, line = status
   -------------------------------------------------------------------------- */
/* note — neutral reference */
.callout[data-callout="note"] { --plx-co: var(--plx-steel); --plx-co-wash: var(--plx-steel-wash); }

/* info — information, blue */
.callout:is([data-callout="info"], [data-callout="information"]) {
  --plx-co: var(--plx-blue); --plx-co-wash: var(--plx-blue-wash);
  --callout-icon: lucide-info;
}

/* tip / hint / important / idea — teal, the house voice */
.callout:is([data-callout="tip"], [data-callout="hint"], [data-callout="important"], [data-callout="idea"]) {
  --plx-co: var(--plx-teal); --plx-co-wash: var(--plx-teal-wash);
}
.callout[data-callout="idea"] { --callout-icon: lucide-lightbulb; }

/* success — green */
.callout:is([data-callout="success"], [data-callout="check"], [data-callout="done"]) {
  --plx-co: var(--plx-green); --plx-co-wash: var(--plx-green-wash);
}

/* question — open, so dashed */
.callout:is([data-callout="question"], [data-callout="help"], [data-callout="faq"]) {
  --plx-co: var(--plx-blue); --plx-co-wash: var(--plx-blue-wash);
  --plx-co-line: dashed;
}

/* warning — amber caution */
.callout:is([data-callout="warning"], [data-callout="caution"], [data-callout="attention"]) {
  --plx-co: var(--plx-amber); --plx-co-wash: var(--plx-amber-wash);
}

/* failure — red, negative result: hatched band */
.callout:is([data-callout="failure"], [data-callout="fail"], [data-callout="missing"]) {
  --plx-co: var(--plx-red); --plx-co-wash: var(--plx-red-wash);
}
.callout:is([data-callout="failure"], [data-callout="fail"], [data-callout="missing"]) > .callout-title {
  background: var(--plx-hatch), linear-gradient(var(--plx-red-wash), var(--plx-red-wash)), var(--plx-paper-2);
}

/* danger / error — destructive: the only filled red band */
.callout:is([data-callout="danger"], [data-callout="error"]) {
  --plx-co: var(--plx-red); --plx-co-wash: var(--plx-red-wash);
}
.callout:is([data-callout="danger"], [data-callout="error"]) > .callout-title {
  background: var(--plx-red);
  color: var(--plx-paper);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--plx-paper) 25%, transparent);
  border-bottom-color: var(--plx-red);
}
.callout:is([data-callout="danger"], [data-callout="error"]) > .callout-title > .callout-icon {
  background: var(--plx-paper);
}
.callout:is([data-callout="danger"], [data-callout="error"]) > .callout-title > .callout-icon .svg-icon { color: var(--plx-red); }
.callout:is([data-callout="danger"], [data-callout="error"]) > .callout-title > .callout-fold { color: var(--plx-paper); }
.theme-dark .callout:is([data-callout="danger"], [data-callout="error"]) > .callout-title {
  background: color-mix(in srgb, var(--plx-red) 42%, var(--plx-paper));
  color: var(--plx-ink);
  border-bottom-color: color-mix(in srgb, var(--plx-red) 60%, var(--plx-paper));
}
.theme-dark .callout:is([data-callout="danger"], [data-callout="error"]) > .callout-title > .callout-icon { background: var(--plx-red); }
.theme-dark .callout:is([data-callout="danger"], [data-callout="error"]) > .callout-title > .callout-icon .svg-icon { color: var(--plx-paper); }

/* bug — red, title in mono like a log line */
.callout[data-callout="bug"] { --plx-co: var(--plx-red); --plx-co-wash: var(--plx-red-wash); }
.callout[data-callout="bug"] > .callout-title {
  font-family: var(--plx-mono);
  font-weight: 600;
  font-size: 10.5px;
  letter-spacing: 0.02em;
}

/* example — violet (a worked formal instance) */
.callout[data-callout="example"] { --plx-co: var(--plx-violet); --plx-co-wash: var(--plx-violet-wash); }

/* todo — open task: amber, dashed, hollow-square icon */
.callout[data-callout="todo"] {
  --plx-co: var(--plx-amber); --plx-co-wash: var(--plx-amber-wash);
  --plx-co-line: dashed;
  --callout-icon: lucide-square;
}

/* time-period (used in the vault's timelines) — steel plate */
.callout[data-callout="time-period"] { --callout-icon: lucide-calendar-range; }


/* ---------- quote / cite ---------- */
.callout[data-callout="quote"] {
  --callout-icon: lucide-quote;
  background: transparent;
  border: 0;
  border-left: 2px solid var(--plx-rule-strong);
  border-radius: 0;
  box-shadow: none;
  margin: 1.2em 0 1.2em 0.4em;
}
.callout[data-callout="quote"] > .callout-title {
  background: none;
  box-shadow: none;
  border: 0;
  min-height: 0;
  padding: 0 0 2px 14px;
  color: var(--plx-ink-3);
  font-size: var(--plx-fs-label);
}
.callout[data-callout="quote"] > .callout-title > .callout-icon { display: none; }
.callout[data-callout="quote"] > .callout-content {
  padding: 0 14px 2px;
  font-family: var(--plx-quote-font);
  font-style: var(--plx-quote-style);
  font-size: 1.14em;
  line-height: 1.5;
  color: var(--plx-ink-2);
}
.callout[data-callout="quote"] > .callout-content em { font-style: normal; }

/* cite — one bibliographic entry: dotted (= reference), hanging indent */
.callout[data-callout="cite"] {
  --callout-icon: lucide-book-marked;
  background: transparent;
  border: 0;
  border-top: 1px dotted var(--plx-rule-strong);
  border-bottom: 1px dotted var(--plx-rule-strong);
  border-radius: 0;
  box-shadow: none;
}
.callout[data-callout="cite"] > .callout-title {
  background: none; box-shadow: none; border: 0; min-height: 0;
  padding: 4px 0 0; color: var(--plx-ink-3); font-size: var(--plx-fs-label);
}
.callout[data-callout="cite"] > .callout-title > .callout-icon { background: var(--plx-ink-3); }
.callout[data-callout="cite"] > .callout-content {
  padding: 2px 0 6px 2em;
  text-indent: -2em;
  font-family: var(--plx-text-serif);
  font-size: 0.9em;
  line-height: 1.5;
}
.callout[data-callout="cite"] > .callout-content code { text-indent: 0; }


/* ---------- abstract — a journal abstract ---------- */
.callout[data-callout="abstract"] {
  background: transparent;
  border: 0;
  border-top: 1px solid var(--plx-rule-soft);
  border-bottom: 1px solid var(--plx-rule-soft);
  border-radius: 0;
  box-shadow: none;
  max-width: 88%;
  margin: 1.6em auto;
}
.callout .callout[data-callout="abstract"] { max-width: none; }
.callout[data-callout="abstract"] > .callout-title {
  justify-content: center;
  background: none;
  box-shadow: none;
  border: 0;
  padding: 8px 0 2px;
  color: var(--plx-ink);
  font-family: var(--plx-serif);
  font-size: 1.02em;
  font-weight: 600;
  text-transform: none;
  font-variant-caps: all-small-caps;
  letter-spacing: 0.09em;
}
.callout[data-callout="abstract"] > .callout-title > .callout-icon { display: none; }
.callout[data-callout="abstract"] > .callout-title > .callout-fold { margin-left: 4px; }
.callout[data-callout="abstract"] > .callout-content {
  padding: 2px 4px 10px;
  font-size: 0.9em;
  line-height: 1.55;
  text-align: justify;
  hyphens: auto;
  color: var(--plx-ink-2);
}

/* ---------- summary / tldr — key-points bar, ruled top and bottom ---------- */
.callout:is([data-callout="summary"], [data-callout="tldr"]) {
  --plx-co: var(--plx-teal); --plx-co-wash: transparent;
  background: transparent;
  border: 0;
  border-top: 2px solid var(--plx-ink-2);
  border-bottom: 1px solid var(--plx-ink-2);
  border-radius: 0;
  box-shadow: none;
}
.callout:is([data-callout="summary"], [data-callout="tldr"]) > .callout-title {
  background: none; box-shadow: none;
  border-bottom: 1px solid var(--plx-rule-soft);
  padding: 4px 0;
  color: var(--plx-ink-2);
}
.callout:is([data-callout="summary"], [data-callout="tldr"]) > .callout-content { padding: 6px 2px 8px; }


/* --------------------------------------------------------------------------
   4 · FORMAL OBJECTS — the amsthm family (typeset, not a coloured box)
   Heading = mono label tab (filled = proven ■, tint = defined, hollow = open □)
   + the object's name in Garamond. Double 3px rule = closed formal object.
   -------------------------------------------------------------------------- */

/* 4a. labels + counters */
.callout:is([data-callout="theorem"], [data-callout="thm"])          { --plx-label: "Theorem"; }
.callout:is([data-callout="lemma"], [data-callout="lem"])            { --plx-label: "Lemma"; }
.callout:is([data-callout="proposition"], [data-callout="prop"])     { --plx-label: "Proposition"; }
.callout:is([data-callout="corollary"], [data-callout="cor"])        { --plx-label: "Corollary"; }
.callout:is([data-callout="claim"], [data-callout="clm"])                                       { --plx-label: "Claim"; }
.callout:is([data-callout="conjecture"], [data-callout="conj"])      { --plx-label: "Conjecture"; }
.callout:is([data-callout="definition"], [data-callout="defn"], [data-callout="def"]) { --plx-label: "Definition"; }
.callout:is([data-callout="axiom"], [data-callout="ax"])                                       { --plx-label: "Axiom"; }
.callout:is([data-callout="postulate"], [data-callout="post"])                                   { --plx-label: "Postulate"; }
.callout:is([data-callout="exercise"], [data-callout="exr"])                                    { --plx-label: "Exercise"; }
.callout:is([data-callout="problem"], [data-callout="prob"])                                     { --plx-label: "Problem"; }
.callout:is([data-callout="remark"], [data-callout="rmk"], [data-callout="rem"])           { --plx-label: "Remark"; }
.callout:is([data-callout="observation"], [data-callout="obs"])      { --plx-label: "Observation"; }
.callout:is([data-callout="notation"], [data-callout="nota"])                                    { --plx-label: "Notation"; }
.callout:is([data-callout="hypothesis"], [data-callout="hyp"])       { --plx-label: "Hypothesis"; }
.callout:is([data-callout="assumption"], [data-callout="asm"])       { --plx-label: "Assumption"; }

/* shared theorem counter: 01, 02, 03 … */
.callout:is(
  [data-callout="theorem"], [data-callout="thm"], [data-callout="lemma"], [data-callout="lem"],
  [data-callout="proposition"], [data-callout="prop"], [data-callout="corollary"], [data-callout="cor"],
  [data-callout="claim"], [data-callout="clm"], [data-callout="conjecture"], [data-callout="conj"],
  [data-callout="definition"], [data-callout="defn"], [data-callout="def"],
  [data-callout="axiom"], [data-callout="ax"], [data-callout="postulate"], [data-callout="post"], [data-callout="exercise"], [data-callout="exr"], [data-callout="problem"], [data-callout="prob"],
  [data-callout="remark"], [data-callout="rmk"], [data-callout="rem"], [data-callout="observation"], [data-callout="obs"],
  [data-callout="notation"], [data-callout="nota"]) {
  --plx-ctr: plx-thm;
  --plx-num: "\a0" counter(plx-thm, decimal-leading-zero);
}
/* hypotheses H.01 and assumptions A.01 — the Drive index voice */
.callout:is([data-callout="hypothesis"], [data-callout="hyp"]) {
  --plx-ctr: plx-hyp;
  --plx-num: "\a0 H." counter(plx-hyp, decimal-leading-zero);
}
.callout:is([data-callout="assumption"], [data-callout="asm"]) {
  --plx-ctr: plx-asm;
  --plx-num: "\a0 A." counter(plx-asm, decimal-leading-zero);
}

/* 4b. the typeset frame (theorem family + hypothesis + assumption) */
.callout:is(
  [data-callout="theorem"], [data-callout="thm"], [data-callout="lemma"], [data-callout="lem"],
  [data-callout="proposition"], [data-callout="prop"], [data-callout="corollary"], [data-callout="cor"],
  [data-callout="claim"], [data-callout="clm"], [data-callout="conjecture"], [data-callout="conj"],
