.callout:is([data-callout="measurement"], [data-callout="readout"], [data-callout="reading"], [data-callout="lcd"]) > .callout-content table {
  border: 0;
  background: transparent;
  min-width: 0;
  margin: 0.2em 0;
  font-size: 1em;
}
.callout:is([data-callout="measurement"], [data-callout="readout"], [data-callout="reading"], [data-callout="lcd"]) > .callout-content :is(th, td) {
  border: 0;
  border-bottom: 1px dotted var(--plx-eink-rule);
  background: transparent;
  color: inherit;
  padding: 2px 14px 2px 0;
  font-family: var(--plx-mono);
}
.callout:is([data-callout="measurement"], [data-callout="readout"], [data-callout="reading"], [data-callout="lcd"]) > .callout-content th {
  font-size: 0.78em;
  font-weight: 600;
  letter-spacing: var(--plx-track);
  border-bottom: 1px solid var(--plx-eink-rule);
  text-transform: none;
}
.callout:is([data-callout="measurement"], [data-callout="readout"], [data-callout="reading"], [data-callout="lcd"]) > .callout-content tbody tr:hover { background: transparent; }

/* ---------- equation — display math, numbered (01) at the right ---------- */
.callout:is([data-callout="equation"], [data-callout="eq"]) {
  --plx-ctr: plx-eq;
  --plx-num: counter(plx-eq, decimal-leading-zero);
  --callout-icon: lucide-sigma;
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  margin: 0.9em 0;
  overflow: visible;
}
.callout:is([data-callout="equation"], [data-callout="eq"]) > .callout-title { display: none; }
.callout:is([data-callout="equation"], [data-callout="eq"]) > .callout-content {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 2.2em;
  padding: 0 4.2em;
  text-align: center;
  overflow: visible;
}
.callout:is([data-callout="equation"], [data-callout="eq"]) > .callout-content :is(.math-block, mjx-container[display="true"], p) {
  margin: 0.25em 0 !important; /* beat 30-reading's display-math margin */
}
.callout:is([data-callout="equation"], [data-callout="eq"]) > .callout-content::after {
  content: "(" var(--plx-num) ")";
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  color: var(--plx-ink-2);
  font-family: var(--plx-mono);
  font-size: 0.86em;
  font-variant-numeric: tabular-nums;
}
.callout:is([data-callout="equation"], [data-callout="eq"]):is([data-callout-metadata*="star"], [data-callout-metadata*="nonum"]) > .callout-content::after { content: none; }
/* |titled — show the title as a small tag on the left */
.callout:is([data-callout="equation"], [data-callout="eq"])[data-callout-metadata*="titled"] > .callout-title {
  display: block;
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  z-index: 1;
  max-width: 4em;
  padding: 0;
  background: none;
  box-shadow: none;
  border: 0;
  min-height: 0;
  color: var(--plx-ink-3);
  font-size: 9.5px;
  line-height: 1.2;
}
.callout:is([data-callout="equation"], [data-callout="eq"])[data-callout-metadata*="titled"] > .callout-title > .callout-icon { display: none; }
.callout:is([data-callout="equation"], [data-callout="eq"]) > .callout-action-buttons { top: -14px; }

/* ---------- caption voice shared by figure / table / algorithm ---------- */
.callout:is([data-callout="figure"], [data-callout="fig"], [data-callout="table"], [data-callout="tab"]) > .callout-title {
  display: block;
  min-height: 0;
  background: none;
  box-shadow: none;
  border: 0;
  color: var(--plx-ink-2);
  font-family: var(--plx-serif);
  font-size: 0.98em;
  font-weight: 400;
  line-height: 1.4;
  letter-spacing: 0;
  text-transform: none;
  text-align: center;
}
.callout:is([data-callout="figure"], [data-callout="fig"], [data-callout="table"], [data-callout="tab"]) > .callout-title > .callout-icon { display: none; }
/* short captions centre, long ones run left-aligned (LaTeX caption pkg) */
.callout:is([data-callout="figure"], [data-callout="fig"], [data-callout="table"], [data-callout="tab"]) > .callout-title > .callout-title-inner {
  display: inline-block;
  text-align: left;
}
.callout:is([data-callout="figure"], [data-callout="fig"], [data-callout="table"], [data-callout="tab"]) > .callout-title > .callout-title-inner::before {
  content: var(--plx-label) var(--plx-num);
  display: inline-block;
  margin-right: 8px;
  padding: 3px 9px 2px 6px;
  vertical-align: 0.1em;
  background: var(--plx-captab-bg);
  color: var(--plx-captab-ink);
  font-family: var(--plx-mono);
  font-size: 10px;
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: var(--plx-track);
  text-transform: uppercase;
  clip-path: var(--plx-clip-br);
}
.callout:is([data-callout="figure"], [data-callout="fig"], [data-callout="table"], [data-callout="tab"])[data-callout-metadata*="anon"] > .callout-title > .callout-title-inner {
  display: inline-block;
  font-size: 0;
}
.callout:is([data-callout="figure"], [data-callout="fig"], [data-callout="table"], [data-callout="tab"])[data-callout-metadata*="anon"] > .callout-title > .callout-title-inner::before { margin-right: 0; }

/* ---------- figure — bordered plate, caption below ---------- */
.callout:is([data-callout="figure"], [data-callout="fig"]) {
  --plx-ctr: plx-fig;
  --plx-label: "Fig.";
  --plx-num: "\a0" counter(plx-fig, decimal-leading-zero);
  --callout-icon: lucide-image;
  display: flex;
  flex-direction: column;
  background: var(--plx-plate);
  border: 1px solid var(--plx-rule-soft);
  border-radius: var(--plx-r);
  box-shadow: none;
  padding: 10px 10px 8px;
}
.callout:is([data-callout="figure"], [data-callout="fig"]) > .callout-title { order: 2; padding: 8px 6px 0; }
.callout:is([data-callout="figure"], [data-callout="fig"]) > .callout-content {
  order: 1;
  padding: 0;
  text-align: center;
}
.callout:is([data-callout="figure"], [data-callout="fig"]) > .callout-content :is(img, svg, video, .image-embed) {
  max-width: 100%;
  margin-inline: auto;
}
.callout:is([data-callout="figure"], [data-callout="fig"]) > .callout-content .math-block { margin: 0.4em 0 !important; }

/* ---------- table — booktabs: caption above, three rules ---------- */
.callout:is([data-callout="table"], [data-callout="tab"]) {
  --plx-ctr: plx-tab;
  --plx-label: "Table";
  --plx-num: "\a0" counter(plx-tab, decimal-leading-zero);
  --callout-icon: lucide-table;
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
}
.callout:is([data-callout="table"], [data-callout="tab"]) > .callout-title { padding: 0 0 6px; }
.callout:is([data-callout="table"], [data-callout="tab"]) > .callout-content { padding: 0; }
.callout:is([data-callout="table"], [data-callout="tab"]) table {
  margin: 0 auto;
  border: 0;
  border-top: 2px solid var(--plx-ink);
  border-bottom: 2px solid var(--plx-ink);
  background: transparent;
  font-variant-numeric: tabular-nums;
}
.callout:is([data-callout="table"], [data-callout="tab"]) :is(th, td) {
  border: 0;
  background: transparent;
  padding: 4px 14px;
  vertical-align: baseline;
}
.callout:is([data-callout="table"], [data-callout="tab"]) thead th {
  border-bottom: 1px solid var(--plx-ink);
  color: var(--plx-ink);
}
.callout:is([data-callout="table"], [data-callout="tab"])[data-callout-metadata*="wide"] table { width: 100%; }

/* ---------- algorithm — top/bottom heavy rules, mono, line numbers ---------- */
.callout:is([data-callout="algorithm"], [data-callout="alg"]) {
  --plx-ctr: plx-alg;
  --plx-num: "\a0" counter(plx-alg, decimal-leading-zero);
  --callout-icon: lucide-binary;
  counter-reset: plx-line;
  background: transparent;
  border: 0;
  border-top: 2px solid var(--plx-ink);
  border-bottom: 2px solid var(--plx-ink);
  border-radius: 0;
  box-shadow: none;
}
.callout:is([data-callout="algorithm"], [data-callout="alg"]) > .callout-title {
  display: block;
  min-height: 0;
  padding: 4px 70px 4px 0;
  background: none;
  box-shadow: none;
  border-bottom: 1px solid var(--plx-ink);
  color: var(--plx-ink);
  font-family: var(--plx-serif);
  font-size: 1.04em;
  font-weight: 400;
  letter-spacing: 0;
  text-transform: none;
}
.callout:is([data-callout="algorithm"], [data-callout="alg"]) > .callout-title > .callout-icon { display: none; }
.callout:is([data-callout="algorithm"], [data-callout="alg"]) > .callout-title > .callout-title-inner { display: inline; }
.callout:is([data-callout="algorithm"], [data-callout="alg"]) > .callout-title::before {
  content: "Algorithm" var(--plx-num);
  display: inline-block;
  margin-right: 8px;
  padding: 3px 9px 2px 6px;
  vertical-align: 0.1em;
  background: var(--plx-captab-bg);
  color: var(--plx-captab-ink);
  font-family: var(--plx-mono);
  font-size: 10px;
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: var(--plx-track);
  text-transform: uppercase;
  clip-path: var(--plx-clip-br);
}
.callout[data-callout="alg"] > .callout-title > .callout-title-inner { display: inline; }
.callout:is([data-callout="algorithm"], [data-callout="alg"]) > .callout-action-buttons { top: 3px; inset-inline-end: 0; }
.callout:is([data-callout="algorithm"], [data-callout="alg"]) > .callout-content {
  position: relative;
  padding: 6px 0 7px;
  font-family: var(--plx-mono);
  font-size: 0.85em;
  line-height: 1.65;
}
.callout:is([data-callout="algorithm"], [data-callout="alg"]) > .callout-content p { margin: 0.2em 0; }
.callout:is([data-callout="algorithm"], [data-callout="alg"]) > .callout-content :is(ol, ul) {
  position: static;
  list-style: none;
  margin: 0;
  padding-left: 2.6em;
}
.callout:is([data-callout="algorithm"], [data-callout="alg"]) > .callout-content :is(ol, ul) :is(ol, ul) {
  padding-left: 1.4em;
  margin-left: 0.25em;
  border-left: 1px solid var(--plx-rule-soft);
}
.callout:is([data-callout="algorithm"], [data-callout="alg"]) > .callout-content li {
  position: static; /* number gutter anchors to the content box, not the li */
  counter-increment: plx-line;
}
.callout:is([data-callout="algorithm"], [data-callout="alg"]) > .callout-content :is(ol, ul)::before,
.callout:is([data-callout="algorithm"], [data-callout="alg"]) > .callout-content li::after { display: none; } /* Obsidian indentation guides — we draw our own */
.callout:is([data-callout="algorithm"], [data-callout="alg"]) > .callout-content li::marker { content: none; }
.callout:is([data-callout="algorithm"], [data-callout="alg"]) > .callout-content li::before {
  content: counter(plx-line) ":";
  position: absolute;
  left: 0;
  width: 1.9em;
  text-align: right;
  color: var(--plx-ink-4);
  font-size: 0.92em;
}
.callout:is([data-callout="algorithm"], [data-callout="alg"]) > .callout-content :is(.list-bullet, .list-collapse-indicator) { display: none; }
.callout:is([data-callout="algorithm"], [data-callout="alg"]) > .callout-content pre {
  margin: 0;
  background: transparent;
  border: 0;
}
.callout:is([data-callout="algorithm"], [data-callout="alg"]) > .callout-content strong { font-weight: 700; color: var(--plx-ink); }


/* --------------------------------------------------------------------------
   6 · WIKI ELEMENTS
   -------------------------------------------------------------------------- */

/* ---------- hatnotes: see also / main article / further ---------- */
.callout[data-callout="seealso"], .callout[data-callout="see-also"], .callout[data-callout="also"]
  { --plx-hat: "See also:"; --callout-icon: lucide-link-2; }
.callout[data-callout="main"], .callout[data-callout="mainarticle"], .callout[data-callout="main-article"]
  { --plx-hat: "Main article:"; --callout-icon: lucide-book-open; }
.callout[data-callout="further"]
  { --plx-hat: "Further information:"; --callout-icon: lucide-library; }

.callout:is([data-callout="seealso"], [data-callout="see-also"], [data-callout="also"],
  [data-callout="main"], [data-callout="mainarticle"], [data-callout="main-article"], [data-callout="further"]) {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  column-gap: 0.35em;
  margin: 0.25em 0 0.9em;
  padding: 0 0 0 1.6em;
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  overflow: visible;
  color: var(--plx-ink-2);
  font-style: italic;
}
.callout:is([data-callout="seealso"], [data-callout="see-also"], [data-callout="also"],
  [data-callout="main"], [data-callout="mainarticle"], [data-callout="main-article"], [data-callout="further"]) > .callout-title {
  display: inline;
  min-height: 0;
  padding: 0;
  background: none;
  box-shadow: none;
  border: 0;
  color: inherit;
  font: inherit;
  letter-spacing: 0;
  text-transform: none;
}
.callout:is([data-callout="seealso"], [data-callout="see-also"], [data-callout="also"],
  [data-callout="main"], [data-callout="mainarticle"], [data-callout="main-article"], [data-callout="further"]) > .callout-title::before {
  content: var(--plx-hat);
}
.callout:is([data-callout="seealso"], [data-callout="see-also"], [data-callout="also"],
  [data-callout="main"], [data-callout="mainarticle"], [data-callout="main-article"], [data-callout="further"]) > .callout-title > :is(.callout-icon, .callout-title-inner, .callout-fold) { display: none; }
/* title-only hatnote: the title IS the text */
.callout:is([data-callout="seealso"], [data-callout="see-also"], [data-callout="also"],
  [data-callout="main"], [data-callout="mainarticle"], [data-callout="main-article"], [data-callout="further"]):not(:has(> .callout-content)) > .callout-title > .callout-title-inner {
  display: inline;
  margin-left: 0.3em;
}
.callout:is([data-callout="seealso"], [data-callout="see-also"], [data-callout="also"],
  [data-callout="main"], [data-callout="mainarticle"], [data-callout="main-article"], [data-callout="further"]) > .callout-content {
  display: inline;
  padding: 0;
  overflow: visible;
}
.callout:is([data-callout="seealso"], [data-callout="see-also"], [data-callout="also"],
  [data-callout="main"], [data-callout="mainarticle"], [data-callout="main-article"], [data-callout="further"]) > .callout-content > p {
  display: inline;
  margin: 0;
}
.callout:is([data-callout="seealso"], [data-callout="see-also"], [data-callout="also"],
  [data-callout="main"], [data-callout="mainarticle"], [data-callout="main-article"], [data-callout="further"]) > .callout-action-buttons { display: none; }

/* ---------- stub — hatched (= incomplete), compact ---------- */
.callout[data-callout="stub"] {
  --plx-co: var(--plx-ink-3); --plx-co-wash: transparent;
  --callout-icon: lucide-sprout;
  display: flex;
  align-items: stretch;
  background: var(--plx-hatch), var(--plx-paper-2);
  border: 1px solid var(--plx-rule);
  font-size: 0.88em;
  max-width: 34rem;
}
.callout[data-callout="stub"] > .callout-title {
  flex: 0 0 auto;
  background: var(--plx-paper-2);
  border: 0;
  border-right: 1px solid var(--plx-rule-soft);
  padding: 5px 10px 5px 5px;
  color: var(--plx-ink-2);
  font-size: var(--plx-fs-label);
}
.callout[data-callout="stub"] > .callout-title > .callout-icon { background: var(--plx-ink-3); }
.callout[data-callout="stub"] > .callout-content {
  display: block;
  flex: 1 1 auto;
  padding: 5px 12px;
  background: color-mix(in srgb, var(--plx-paper) 55%, transparent);
  color: var(--plx-ink-2);
}
.callout[data-callout="stub"] > .callout-content::before {
  content: "This article is a stub. ";
  font-style: italic;
}
.callout[data-callout="stub"] > .callout-content > p { display: inline; }
.callout[data-callout="stub"]:not(:has(> .callout-content)) > .callout-title::after {
  content: "This article is a stub.";
  margin-left: 6px;
  font-family: var(--plx-sans);
  font-weight: 400;
  font-style: italic;
  text-transform: none;
  letter-spacing: 0;
}
.callout[data-callout="stub"] > .callout-action-buttons { display: none; }

/* ---------- citation needed — small tag, right-aligned; note on hover ---------- */
.callout:is([data-callout="citation-needed"], [data-callout="cn"]) {
  width: fit-content;
  margin: -0.85em 0 0.9em auto;
  padding: 0;
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  overflow: visible;
}
.callout:is([data-callout="citation-needed"], [data-callout="cn"]) > .callout-title {
  display: inline;
  min-height: 0;
  padding: 0;
  background: none;
  box-shadow: none;
  border: 0;
  color: var(--plx-teal);
  font-family: var(--plx-sans);
  font-size: 0.74em;
  font-style: italic;
  font-weight: 400;
  letter-spacing: 0;
  text-transform: none;
  cursor: help;
}
.callout:is([data-callout="citation-needed"], [data-callout="cn"]) > .callout-title::before {
  content: "[citation needed]";
  border-bottom: 1px dashed currentColor;
}
.callout:is([data-callout="citation-needed"], [data-callout="cn"]) > .callout-title > * { display: none; }
.callout:is([data-callout="citation-needed"], [data-callout="cn"]) > .callout-content {
  display: none;
  position: absolute;
  right: 0;
  top: 1.4em;
  z-index: 5;
  width: max-content;
  max-width: 22rem;
  padding: 5px 9px;
  background: var(--plx-paper);
  border: 1px dotted var(--plx-rule-strong);
  box-shadow: var(--plx-float);
  font-size: 0.8em;
  color: var(--plx-ink-2);
}
.callout:is([data-callout="citation-needed"], [data-callout="cn"]):hover > .callout-content { display: block; }
.callout:is([data-callout="citation-needed"], [data-callout="cn"]) > .callout-action-buttons { display: none; }

/* ---------- disambiguation — dotted (= points elsewhere) ---------- */
.callout:is([data-callout="disambiguation"], [data-callout="disambig"]) {
  --plx-co: var(--plx-ink-3); --plx-co-wash: transparent;
  --callout-icon: lucide-signpost;
  background: transparent;
  border: 1px dotted var(--plx-rule-strong);
}
.callout:is([data-callout="disambiguation"], [data-callout="disambig"]) > .callout-title {
  background: none; box-shadow: none;
  border-bottom: 1px dotted var(--plx-rule);
  color: var(--plx-ink-2);
}
.callout:is([data-callout="disambiguation"], [data-callout="disambig"]) > .callout-title > .callout-icon { background: var(--plx-ink-3); }
.callout:is([data-callout="disambiguation"], [data-callout="disambig"]) > .callout-content > ul {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(21rem, 1fr));
  column-gap: 2rem;
}

/* ---------- under construction — amber, dashed, hatched ---------- */
.callout:is([data-callout="wip"], [data-callout="construction"], [data-callout="under-construction"]) {
  --plx-co: var(--plx-amber); --plx-co-wash: var(--plx-amber-wash);
  --plx-co-line: dashed;
  --plx-co-edge: var(--plx-amber);
  --callout-icon: lucide-construction;
  background: var(--plx-hatch), linear-gradient(var(--plx-amber-wash), var(--plx-amber-wash)), var(--plx-plate);
}
.callout:is([data-callout="wip"], [data-callout="construction"], [data-callout="under-construction"]) > .callout-title {
  background: var(--plx-paper-2);
  border-bottom: 1px dashed var(--plx-amber);
}
.callout:is([data-callout="wip"], [data-callout="construction"], [data-callout="under-construction"]) > .callout-content {
  margin: 6px;
  padding: 5px 9px;
  background: var(--plx-plate);
}

/* ---------- references / bibliography — numbered [n], hanging ---------- */
.callout:is([data-callout="references"], [data-callout="refs"], [data-callout="bibliography"]) {
  --callout-icon: lucide-library;
  background: transparent;
  border: 0;
  border-top: 1px dotted var(--plx-rule-strong);
  border-radius: 0;
  box-shadow: none;
  margin-top: 2em;
}
.callout:is([data-callout="references"], [data-callout="refs"], [data-callout="bibliography"]) > .callout-title {
  background: none; box-shadow: none; border: 0;
  padding: 8px 70px 4px 0;
  color: var(--plx-ink);
  font-family: var(--plx-serif);
  font-size: 1.15em;
  font-weight: 600;
  text-transform: none;
  font-variant-caps: all-small-caps;
  letter-spacing: 0.08em;
}
.callout:is([data-callout="references"], [data-callout="refs"], [data-callout="bibliography"]) > .callout-title > .callout-icon { display: none; }
.callout:is([data-callout="references"], [data-callout="refs"], [data-callout="bibliography"]) > .callout-action-buttons { inset-inline-end: 0; }
.callout:is([data-callout="references"], [data-callout="refs"], [data-callout="bibliography"]) > .callout-content {
  padding: 0;
  font-size: 0.86em;
  line-height: 1.5;
}
.callout:is([data-callout="references"], [data-callout="refs"], [data-callout="bibliography"]) > .callout-content ol {
  counter-reset: plx-ref;
  list-style: none;
  padding-left: 3em;
}
.callout:is([data-callout="references"], [data-callout="refs"], [data-callout="bibliography"]) > .callout-content ol > li {
  counter-increment: plx-ref;
  position: relative;
  margin: 0.25em 0;
}
.callout:is([data-callout="references"], [data-callout="refs"], [data-callout="bibliography"]) > .callout-content ol > li::marker { content: none; }
.callout:is([data-callout="references"], [data-callout="refs"], [data-callout="bibliography"]) > .callout-content ol > li::before {
  content: "[" counter(plx-ref, decimal-leading-zero) "]";
  position: absolute;
  left: -3em;
  width: 2.5em;
  text-align: right;
  color: var(--plx-ink-3);
  font-family: var(--plx-mono);
  font-size: 0.92em;
}
.callout:is([data-callout="references"], [data-callout="refs"], [data-callout="bibliography"]) > .callout-content ul {
  list-style: none;
  padding-left: 2em;
}
.callout:is([data-callout="references"], [data-callout="refs"], [data-callout="bibliography"]) > .callout-content ul > li { text-indent: -2em; }
.callout:is([data-callout="references"], [data-callout="refs"], [data-callout="bibliography"]) > .callout-content ul > li::marker { content: none; }
.callout:is([data-callout="references"], [data-callout="refs"], [data-callout="bibliography"]) > .callout-content :is(.list-bullet, .list-collapse-indicator) { display: none; }

/* ---------- navbox / topic — centred navigation box ---------- */
.callout:is([data-callout="navbox"], [data-callout="topic"], [data-callout="navbox-simple"]) {
  --plx-co: var(--plx-teal); --plx-co-wash: transparent;
  --callout-icon: none;
  border: 1px solid var(--plx-rule);
}
.callout:is([data-callout="navbox"], [data-callout="topic"], [data-callout="navbox-simple"]) > .callout-title {
  justify-content: center;
  padding: 4px 10px;
  background: var(--plx-paper-2);
  color: var(--plx-ink);
  font-family: var(--plx-serif);
  font-size: 1.02em;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: none;
}
.callout:is([data-callout="navbox"], [data-callout="topic"], [data-callout="navbox-simple"]) > .callout-title > .callout-icon { display: none; }
.callout:is([data-callout="navbox"], [data-callout="topic"], [data-callout="navbox-simple"]) > .callout-title > .callout-fold { margin-left: 6px; }
.callout:is([data-callout="navbox"], [data-callout="topic"], [data-callout="navbox-simple"]) > .callout-content {
  padding: 6px 14px 7px;
  text-align: center;
  font-size: 0.9em;
  line-height: 1.7;
}

/* ---------- infobox — floats right in reading view ---------- */
.callout[data-callout="infobox"] {
  --plx-co: var(--plx-slate); --plx-co-wash: transparent;
  --callout-icon: none;
  float: right;
  clear: right;
  width: 18rem;
  margin: 0.3em 0 1em 1.6em;
  background: var(--plx-paper-2);
  border: 1px solid var(--plx-rule);
  font-size: 0.86em;
  line-height: 1.4;
}
.callout[data-callout="infobox"] > .callout-title {
  justify-content: center;
  padding: 6px 10px;
  background: var(--plx-band);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--plx-slate-ink) 12%, transparent);
  border-bottom: 1px solid var(--plx-slate);
  color: var(--plx-slate-ink);
  font-family: var(--plx-serif);
  font-size: 1.22em;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: none;
  text-align: center;
}
.callout[data-callout="infobox"] > .callout-title > .callout-icon { display: none; }
.callout[data-callout="infobox"] > .callout-title > .callout-fold { color: var(--plx-slate-ink); margin-left: 6px; }
.callout[data-callout="infobox"] > .callout-action-buttons { top: 6px; inset-inline-end: 4px; }
.callout[data-callout="infobox"] > .callout-content { padding: 6px 8px 8px; }
.callout[data-callout="infobox"] > .callout-content > p { margin: 0.4em 0; }
.callout[data-callout="infobox"] > .callout-content :is(img, .image-embed) {
  display: block;
  max-width: 100%;
  margin: 0 auto;
}
.callout[data-callout="infobox"] > .callout-content :is(.table-wrapper, table) { width: 100%; }
.callout[data-callout="infobox"] > .callout-content table {
  margin: 0.3em 0;
  min-width: 0;
  border: 0;
  background: transparent;
  font-size: 1em;
}
.callout[data-callout="infobox"] > .callout-content :is(th, td) {
  border: 0;
  border-top: 1px solid var(--plx-rule-soft);
  padding: 3px 4px;
  background: transparent;
  vertical-align: top;
}
/* header row → a sub-heading strip; hidden when left empty (| | |) */
.callout[data-callout="infobox"] > .callout-content thead th {
  border-top: 0;
  border-bottom: 1px solid var(--plx-rule);
  background: var(--plx-case-hi);
  color: var(--plx-ink-2);
  font-size: var(--plx-fs-label);
  text-align: center;
}
.callout[data-callout="infobox"] > .callout-content thead:not(:has(th:not(:empty))) { display: none; }
.callout[data-callout="infobox"] > .callout-content tbody td:first-child {
  width: 40%;
  color: var(--plx-ink-2);
  font-family: var(--plx-ui-cond);
  font-size: var(--plx-fs-small);
  font-weight: 700;
  letter-spacing: 0.02em;
}
.callout[data-callout="infobox"] > .callout-content tbody tr:first-child td { border-top: 0; }
.callout[data-callout="infobox"] > .callout-content tbody tr:hover { background: transparent; }
.callout[data-callout="infobox"][data-callout-metadata*="left"] {
  float: left;
  clear: left;
  margin: 0.3em 1.6em 1em 0;
}
/* no float: Live Preview, nested, |nofloat |wide, and narrow panes */
.callout[data-callout="infobox"]:is([data-callout-metadata*="nofloat"], [data-callout-metadata*="wide"]),
.markdown-source-view .callout[data-callout="infobox"],
.callout .callout[data-callout="infobox"] {
  float: none;
  margin: 0.8em 0 0.8em auto;
}
.callout[data-callout="infobox"][data-callout-metadata*="wide"] { width: auto; }
@container plx-note (max-width: 700px) {
  .callout[data-callout="infobox"] {
    float: none;
    width: auto;
    margin: 0.8em 0;
  }
}

/* ---------- compact academic objects (figure / table / equation / algorithm) ---------- */
.callout:is([data-callout="figure"], [data-callout="fig"]) { padding: 6px 8px 5px; margin-block: 0.8em; }
.callout:is([data-callout="figure"], [data-callout="fig"]) > .callout-title { padding: 5px 4px 0; line-height: 1.35; }
.callout:is([data-callout="table"], [data-callout="tab"]) { margin-block: 0.8em; }
.callout:is([data-callout="table"], [data-callout="tab"]) > .callout-title { padding: 0 0 4px; line-height: 1.35; position: relative; z-index: 0; }
.callout:is([data-callout="table"], [data-callout="tab"]) > .callout-content { position: relative; z-index: 1; }
.callout:is([data-callout="table"], [data-callout="tab"]) :is(th, td) { padding: 2px 10px !important; line-height: 1.4 !important; }
.callout:is([data-callout="table"], [data-callout="tab"]) thead th { background: transparent !important; vertical-align: bottom; }
.callout:is([data-callout="figure"], [data-callout="fig"], [data-callout="table"], [data-callout="tab"]) > .callout-title > .callout-title-inner::before {
  padding: 2px 7px 1px 5px; margin-right: 6px; vertical-align: 0.08em; line-height: 1.25;
}
.callout:is([data-callout="algorithm"], [data-callout="alg"]) > .callout-content { line-height: 1.45; }
.callout:is([data-callout="equation"], [data-callout="eq"]) { margin-block: 0.4em; }
.callout:is([data-callout="equation"], [data-callout="eq"]) .math-block { margin: 0.25em 0 !important; }
.callout:is([data-callout="table"], [data-callout="tab"]) :is(thead, thead tr, tbody tr) { background: transparent !important; }

/* ---------- revision: balance + attachment ----------
   Infobox: labels and values share one size (Wikipedia-style), labels bold
   in the reading face, so math in a label matches math in a value.
   Titled equation: the name sits under its number at the right, attached to
   the tag it explains, not stranded at the left margin. */
.callout[data-callout="infobox"] > .callout-content tbody td {
  font-size: calc(var(--font-text-size) * 0.86) !important; /* = wikitable cells */
}
.callout[data-callout="infobox"] > .callout-content tbody td:first-child {
  font-family: inherit;
  font-weight: 650;
  letter-spacing: 0;
}
.callout:is([data-callout="equation"], [data-callout="eq"])[data-callout-metadata*="titled"] > .callout-title {
  left: auto;
  right: 0;
  top: calc(50% + 0.95em);
  transform: none;
  max-width: 7em;
  text-align: right;
  font-family: var(--plx-reading);
  font-style: italic;
  font-size: 0.78em;
  font-weight: 400;
}

/* star / nonum, enforced: the figure, table, algorithm and equation blocks set
   their own counter later in this file at equal specificity, so the generic
   flag rule lost and those objects kept numbering (the equation even advanced
   the counter while hiding the number). Doubled class = higher specificity. */
.callout.callout:is([data-callout-metadata*="star"], [data-callout-metadata*="nonum"]) {
  --plx-ctr: none;
  --plx-num: "";
}


/* ---- a-base/50-properties.css ---- */
/* ==========================================================================
   50 · PROPERTIES — small mono spec sheet
   Base: monospaced, ~10.5px, 18px rows. Five variants (Style Settings →
   "Properties layout", body classes):
     (default)            LEDGER  — two-column mono table, dotted rules
     .plx-props-strip     STRIP   — one wrapped metadata line under the title
     .plx-props-margin    MARGIN  — narrow card floated right (reading view)
     .plx-props-lcd       LCD     — recessed Casio display panel
     .plx-props-tucked    TUCKED  — only the label line until hovered/focused
   ========================================================================== */

body {
  --plx-prop-fs: 11.5px;
  --plx-prop-row: 21px;
  --plx-prop-key-w: 9em;
}

/* ---------- Base (LEDGER) ---------- */
.metadata-container {
  --metadata-label-width: var(--plx-prop-key-w);
  margin: 0.35rem 0 1.4rem !important;
  padding: 0 !important;
  border: none;
  border-top: 1px solid var(--plx-rule-soft);
  border-bottom: 1px solid var(--plx-rule-soft);
  border-radius: 0;
  background: transparent;
  font-family: var(--plx-mono);
  font-size: var(--plx-prop-fs);
  line-height: 1.35;
  color: var(--plx-ink-2);
}

.metadata-properties-heading {
  margin: 0 !important;
  padding: 1px 2px !important;
  gap: 3px;
  min-height: 0;
  cursor: pointer;
  border-radius: 0;
}
.metadata-properties-heading:hover { background: var(--plx-lcd-2); }
.metadata-properties-title {
  font-size: 9.5px !important;
  font-weight: 400 !important;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--plx-ink-3) !important;
}
.metadata-container[data-property-count] .metadata-properties-title::after {
  content: " [" attr(data-property-count) "]";
  letter-spacing: 0;
  color: var(--plx-ink-4);
}
.metadata-properties-heading .collapse-indicator { color: var(--plx-ink-4); --icon-size: 9px; width: 10px; }
.metadata-container.is-collapsed { border-bottom: none; }

.metadata-content { padding: 0 0 2px; }
.metadata-properties { gap: 0; }
.metadata-property {
  padding: 0 2px !important;
  min-height: var(--plx-prop-row);
  border-radius: 0 !important;
  align-items: center;
  gap: 0;
  border-top: 1px dotted var(--plx-rule-soft);
}
.metadata-property:hover { background: var(--plx-lcd-2) !important; }
.metadata-property:focus-within { background: var(--plx-lcd) !important; box-shadow: inset 2px 0 0 var(--plx-teal); }

.metadata-property-key { border: none !important; background: transparent !important; align-items: center; min-height: var(--plx-prop-row); }
.metadata-property-icon { color: var(--plx-ink-4); --icon-size: 10px; min-width: 14px; width: 14px; padding: 0 !important; }
.metadata-property-key-input {
  font-size: var(--plx-prop-fs) !important;
  color: var(--plx-ink-3) !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 4px 0 2px !important;
  height: var(--plx-prop-row);
  min-height: 0;
  text-transform: none;
}
.metadata-property-value { border: none !important; background: transparent !important; min-height: var(--plx-prop-row); }
.metadata-property-value input,
.metadata-property-value .metadata-input-longtext,
.metadata-property-value .metadata-input-text {
  font-size: var(--plx-prop-fs) !important;
  color: var(--plx-ink) !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 3px !important;
  min-height: var(--plx-prop-row);
  height: auto;
  line-height: var(--plx-prop-row);
  font-variant-numeric: tabular-nums;
}
.metadata-property-value input:focus,
.metadata-property-value .metadata-input-longtext:focus {
  background: var(--plx-well) !important;
  box-shadow: inset 0 0 0 1px var(--plx-teal) !important;
}
.metadata-property-value input[type="date"]::-webkit-calendar-picker-indicator,
.metadata-property-value input[type="datetime-local"]::-webkit-calendar-picker-indicator { opacity: 0.35; width: 10px; height: 10px; }
.metadata-property-value .metadata-input-checkbox { width: 11px; height: 11px; margin-inline-start: 3px; }

/* list values → bracketed tokens, not pills */
.multi-select-container { gap: 0 4px; padding: 0 2px !important; border: none !important; background: transparent !important; box-shadow: none !important; min-height: var(--plx-prop-row); }
.multi-select-pill {
  border: none !important;
  border-radius: 0 !important;
  background: transparent !important;
  color: var(--plx-ink) !important;
  padding: 0 !important;
  height: var(--plx-prop-row);
  font-size: var(--plx-prop-fs) !important;
  box-shadow: none !important;
}
.multi-select-pill::after { content: ","; color: var(--plx-ink-4); }
.multi-select-pill:last-of-type::after { content: none; }
.metadata-property[data-property-key="tags"] .multi-select-pill-content::before { content: "#"; color: var(--plx-ink-4); }
.multi-select-pill:hover { color: var(--plx-teal) !important; background: var(--plx-teal-wash) !important; }
.multi-select-pill-remove-button { display: none; --icon-size: 9px; }
.multi-select-pill:hover .multi-select-pill-remove-button { display: flex; color: var(--plx-red) !important; }
.multi-select-input { font-size: var(--plx-prop-fs) !important; min-width: 2em; }
.metadata-property-value .internal-link,
.metadata-link-inner { color: var(--plx-teal) !important; text-decoration: underline dotted; text-underline-offset: 2px; }
.metadata-input-longtext:empty::before, .metadata-property-value input::placeholder { color: var(--plx-ink-4) !important; font-style: normal; content: "—"; }

.metadata-add-button {
  margin: 0 !important; padding: 0 4px !important;
  font-size: 9.5px !important; text-transform: uppercase; letter-spacing: 0.1em;
  color: var(--plx-ink-4) !important;
  opacity: 0; transition: opacity 120ms; border-radius: 0 !important;
  min-height: 16px;
  --icon-size: 9px;
}
.metadata-container:hover .metadata-add-button,
.metadata-container:focus-within .metadata-add-button { opacity: 1; }
.metadata-add-button:hover { color: var(--plx-teal) !important; background: var(--plx-lcd-2) !important; }

/* ---------- STRIP — one wrapped line: key value · key value ---------- */
body.plx-props-strip .metadata-container { border-bottom: none; border-top: none; margin-top: 0.1rem !important; }
body.plx-props-strip .metadata-properties-heading { display: none; }
body.plx-props-strip .metadata-container.is-collapsed .metadata-content { display: block !important; }
body.plx-props-strip .metadata-properties { display: flex; flex-wrap: wrap; gap: 0 14px; }
body.plx-props-strip .metadata-property { border: none; width: auto; padding: 0 !important; }
body.plx-props-strip .metadata-property-icon { display: none; }
body.plx-props-strip .metadata-property-key { width: auto !important; min-width: 0; }
body.plx-props-strip .metadata-property-key-input { width: auto; field-sizing: content; color: var(--plx-ink-4) !important; padding-inline-end: 3px !important; }
body.plx-props-strip .metadata-property-key-input::after { content: ":"; }
body.plx-props-strip .metadata-property-value { flex: 0 1 auto; width: auto; }
body.plx-props-strip .metadata-property-value input { field-sizing: content; width: auto; max-width: 22em; }
body.plx-props-strip .metadata-add-button { display: none; }
body.plx-props-strip .metadata-container:hover .metadata-add-button { display: flex; }

/* ---------- MARGIN — right-floated narrow card (reading view) ---------- */
body.plx-props-margin .markdown-reading-view .metadata-container {
  float: right;
  width: 16rem;
  margin: 0.2rem 0 1rem 1.5rem !important;
  border: 1px solid var(--plx-rule);
  background: var(--plx-paper-2);
  position: relative;
  z-index: 1;
}
body.plx-props-margin .markdown-reading-view .metadata-properties-heading {
  background: var(--plx-band);
  padding: 2px 6px !important;
}
body.plx-props-margin .markdown-reading-view .metadata-properties-title,
body.plx-props-margin .markdown-reading-view .metadata-properties-heading .collapse-indicator { color: var(--plx-slate-ink) !important; }
body.plx-props-margin .markdown-reading-view .metadata-container { --plx-prop-key-w: 6.5em; }
body.plx-props-margin .markdown-reading-view .metadata-property { padding: 0 5px !important; }
body.plx-props-margin .markdown-reading-view .metadata-property-icon { display: none; }

/* ---------- LCD — Casio display panel ---------- */
body.plx-props-lcd .metadata-container {
  border: 1px solid var(--plx-rule-strong);
  border-radius: var(--plx-r);
  background: var(--plx-eink);
  box-shadow: var(--plx-recessed);
  padding: 2px 6px 3px !important;
  color: var(--plx-eink-ink);
}
body.plx-props-lcd .metadata-property { border-top: 1px solid color-mix(in srgb, var(--plx-lcd-ink) 10%, transparent); }
body.plx-props-lcd .metadata-property:hover { background: color-mix(in srgb, var(--plx-lcd-ink) 6%, transparent) !important; }
body.plx-props-lcd .metadata-property-value input,
body.plx-props-lcd .metadata-property-value .metadata-input-longtext,
body.plx-props-lcd .multi-select-pill { color: var(--plx-lcd-ink) !important; }
body.plx-props-lcd .metadata-property-key-input,
body.plx-props-lcd .metadata-properties-title { color: color-mix(in srgb, var(--plx-lcd-ink) 60%, transparent) !important; }

/* ---------- TUCKED — label line only until hover / focus ---------- */
body.plx-props-tucked .metadata-container:not(:hover):not(:focus-within) .metadata-content { display: none; }
body.plx-props-tucked .metadata-container:not(:hover):not(:focus-within) { border-bottom: none; }
body.plx-props-tucked .metadata-properties-title::before { content: "▸ "; color: var(--plx-ink-4); }
body.plx-props-tucked .metadata-container:hover .metadata-properties-title::before { content: "▾ "; }

/* ---------- other options ---------- */
body.plx-properties-hide-add .metadata-add-button { display: none !important; }
body.plx-properties-reading-hidden .markdown-reading-view .metadata-container { display: none; }

/* File-properties side pane, all-properties pane */
.workspace-leaf-content[data-type="file-properties"] .metadata-container { border-top: none; }
.workspace-leaf-content[data-type="all-properties"] .tree-item-self { font-family: var(--plx-mono); font-size: 11px; }
.workspace-leaf-content[data-type="all-properties"] .tree-item-flair { font-family: var(--plx-mono); }

/* frontmatter in source mode */
.cm-hmd-frontmatter, .HyperMD-frontmatter { font-family: var(--plx-mono); font-size: 0.8em; color: var(--plx-ink-2); }
.HyperMD-frontmatter { background: var(--plx-paper-2); }

/* ---------- Label chip: the "PROPERTIES [n]" tab with an angled corner ---------- */
.metadata-properties-heading { padding: 0 !important; }
.metadata-properties-heading:hover { background: transparent; }
.metadata-properties-heading .collapse-indicator { margin-inline-start: 2px; }
.metadata-properties-title {
  background: var(--plx-case);
  color: var(--plx-ink-2) !important;
  padding: 1px 14px 1px 6px;
  border-radius: 0 0 0 var(--plx-r);
  clip-path: var(--plx-clip-br);
}
.metadata-properties-heading:hover .metadata-properties-title { background: var(--plx-lcd); color: var(--plx-lcd-ink) !important; }
body.plx-props-lcd .metadata-properties-title { background: transparent; clip-path: none; padding-inline: 0; }

/* sizing fixes: Obsidian sizes rows from --input-height */
.metadata-container { --input-height: var(--plx-prop-row); }
.metadata-property-key, .metadata-property-value { height: auto; }
/* list separators only between items */
.multi-select-pill::after { content: none !important; }
.multi-select-pill:has(+ .multi-select-pill)::after { content: "," !important; color: var(--plx-ink-4); }
/* strip: horizontal flow */
body.plx-props-strip .metadata-properties { flex-direction: row; align-items: baseline; }
body.plx-props-strip .metadata-property { flex: 0 0 auto; }
body.plx-props-strip .metadata-property-key-input { min-width: 0; }

/* count readout not possible from CSS (attribute lives on the parent) */
.metadata-container[data-property-count] .metadata-properties-title::after { content: none; }
/* margin card: keep key + value on one line, readable title chip */
body.plx-props-margin .markdown-reading-view .metadata-property { flex-wrap: nowrap; }
body.plx-props-margin .markdown-reading-view .metadata-property-key { width: 6.5em !important; min-width: 6.5em; }
body.plx-props-margin .markdown-reading-view .metadata-property-value { min-width: 0; }
body.plx-props-margin .markdown-reading-view .metadata-properties-title { background: transparent; clip-path: none; padding-inline: 0; }
body.plx-props-margin .markdown-reading-view .metadata-properties-heading:hover .metadata-properties-title { background: transparent; color: var(--plx-slate-ink) !important; }


/* ==========================================================================
   Readability pass (rev. 2): the small-text serif for keys and values,
   mono only for numbers/dates; uniform 23px rows; square focus; no bubbles.
   ========================================================================== */
body { --plx-prop-fs: 13px; --plx-prop-key-fs: 12px; --plx-prop-row: 23px; --plx-prop-key-w: 8.5em; }
.metadata-container { font-family: var(--plx-small); font-size: var(--plx-prop-fs); }
.metadata-properties-title { font-family: var(--plx-ui-cond) !important; font-size: 10px !important; letter-spacing: 0.1em; }
.metadata-property-key-input {
  font-family: var(--plx-small) !important;
  font-size: var(--plx-prop-key-fs) !important;
  font-style: italic;
  color: var(--plx-ink-3) !important;
  letter-spacing: 0.01em;
}
.metadata-property-value input,
.metadata-property-value .metadata-input-longtext,
.metadata-property-value .metadata-input-text,
.multi-select-pill, .multi-select-input {
  font-family: var(--plx-small) !important;
  font-size: var(--plx-prop-fs) !important;
}
/* numbers, dates, tags: mono so they align */
.metadata-property[data-property-type="number"] input,
.metadata-property-value input[type="number"],
.metadata-property-value input[type="date"],
.metadata-property-value input[type="datetime-local"],
.metadata-property[data-property-key="tags"] .multi-select-pill,
.metadata-property[data-property-key="cssclasses"] .multi-select-pill {
  font-family: var(--plx-mono) !important;
  font-size: 11.5px !important;
}
/* one row height for every value type */
.metadata-property, .metadata-property-key, .metadata-property-value { min-height: var(--plx-prop-row); }
.metadata-property-value { align-items: center; }
.metadata-property-value input[type="date"], .metadata-property-value input[type="datetime-local"],
.metadata-property-value input[type="number"] { height: var(--plx-prop-row) !important; line-height: var(--plx-prop-row); }
.metadata-property-value:has(.metadata-input-checkbox) { display: flex; align-items: center; padding-inline-start: 3px; }
.metadata-property-icon { --icon-size: 11px; color: var(--plx-ink-4); }
/* list items: plain text with thin separators; square focus, no rounded bubble */
.multi-select-pill { line-height: var(--plx-prop-row); height: var(--plx-prop-row); }
.multi-select-pill:focus, .multi-select-pill:focus-visible, .multi-select-pill.is-active {
  outline: none !important;
  border-radius: 0 !important;
  background: var(--plx-lcd) !important;
  box-shadow: inset 0 -1px 0 var(--plx-teal) !important;
}
.multi-select-pill:has(+ .multi-select-pill)::after { content: " ·" !important; color: var(--plx-ink-4); }
.multi-select-container:focus-within { box-shadow: none !important; }
.metadata-property:focus-within { box-shadow: inset 2px 0 0 var(--plx-teal) !important; }
/* the same face for other small text */
.markdown-rendered section.footnotes, .footnotes li,
.setting-item-description, .callout[data-callout="figure"] .callout-title-inner,
.image-embed::after { font-family: var(--plx-small); }

/* checkbox values: a real square, not caught by the value-input reset */
.metadata-property-value input.metadata-input-checkbox {
  width: 13px !important; height: 13px !important; min-height: 0 !important;
  margin: 0 0 0 3px; padding: 0 !important;
  border: 1px solid var(--plx-rule-strong) !important;
  border-radius: 1px !important;
  background: var(--plx-well) !important;
  box-shadow: var(--plx-recessed) !important;
}
.metadata-property-value input.metadata-input-checkbox:checked {
  background-color: var(--plx-teal) !important;
  border-color: color-mix(in srgb, var(--plx-teal) 60%, black) !important;
}
/* dates: Berkeley Mono collides in Chrome's date field; use Plex Mono there */
.metadata-property-value input[type="date"], .metadata-property-value input[type="datetime-local"] {
  font-family: "IBM Plex Mono", "JetBrains Mono", Consolas, monospace !important;
  font-size: 11.5px !important;
  width: auto; field-sizing: content;
}


/* ---- a-base/60-plugins.css ---- */
/* ==========================================================================
   60 · PLUGINS & CORE VIEWS
   Compatibility for common community plugins:
   Style Settings, Iconize (tree: 20), File Explorer Note Count (tree: 20),
   Recent Files (tree: 20), Callout Copy Buttons (callouts: 40), Homepage,
   Widgets, Tag Wrangler, Multi-Tag, Advanced Canvas, Excalidraw,
   Agent Client — plus core Canvas, Graph, Bases, Outline, Calendar/Kanban
   (installed, disabled) so enabling them later stays on-theme.
   ========================================================================== */

/* ---------- Typography options (Style Settings) ---------- */
body.plx-display-eb { --plx-display: var(--plx-serif); --plx-display-weight: 500; }
body.plx-body-plex { --font-text-theme: var(--plx-sans); }
body.plx-body-inter { --font-text-theme: "Inter", var(--plx-sans); }
body.plx-body-instrument { --font-text-theme: "Instrument Sans", var(--plx-sans); }
body.plx-body-golos { --font-text-theme: "Golos Text", var(--plx-sans); }
body.plx-body-verdana { --font-text-theme: Verdana, var(--plx-sans); }
body.plx-body-serif { --font-text-theme: var(--plx-text-serif); }
body.plx-body-sitka { --font-text-theme: "Sitka Text", var(--plx-text-serif); }
body.plx-body-georgia { --font-text-theme: Georgia, var(--plx-text-serif); }
body.plx-body-constantia { --font-text-theme: var(--plx-reading); }
body.plx-body-palatino { --font-text-theme: "Palatino Linotype", "Book Antiqua", var(--plx-text-serif); }
body.plx-body-concrete { --font-text-theme: "CMU Concrete", var(--plx-text-serif); }
body.plx-body-cmu { --font-text-theme: "CMU Serif", "Constantia", "IBM Plex Serif", Georgia, serif; }   /* A4-10: was the Constantia stack */
body.plx-body-garamond { --font-text-theme: var(--plx-serif); }
body.plx-ui-mono { --font-interface-theme: var(--plx-mono); }
body.plx-headings-sans {
  --h1-font: var(--plx-ui); --h2-font: var(--plx-ui); --h3-font: var(--plx-ui); --h4-font: var(--plx-ui);
  --inline-title-font: var(--plx-ui);
}
body.plx-flat .clickable-icon:hover,
body.plx-flat button:not(.clickable-icon),
body.plx-flat .side-dock-ribbon-action,
body.plx-flat .nav-action-button { box-shadow: none !important; background-image: none !important; }
body.plx-wide-lines { --file-line-width: 58rem; }

/* ---------- Style Settings plugin's own panel ---------- */
.style-settings-heading {
  border-bottom: 1px solid var(--plx-rule-soft);
  padding: 6px 0;
}
.style-settings-heading[data-level="0"] .setting-item-name { font-family: var(--plx-serif); font-size: 1.2em; }
.style-settings-collapse-indicator { color: var(--plx-ink-3); }
.style-settings-container { border-inline-start: 1px solid var(--plx-rule-soft); padding-inline-start: 10px; }

/* Canvas, Graph and Bases live in 70-views.css */

/* ---------- Outline (core) ---------- */
.workspace-leaf-content[data-type="outline"] .tree-item-inner { font-size: 12.5px; }

/* ---------- Homepage plugin ---------- */
.nv-command-pill {
  font-family: var(--plx-mono);
  border: 1px solid var(--plx-rule) !important;
  border-radius: var(--plx-r) !important;
  background: var(--plx-key-face) !important;
}

/* ---------- Widgets plugin (countdown, counter, quote) ---------- */
.Countdown_Container, .Counter__container, .Quote_Container {
  border: 1px solid var(--plx-rule-strong);
  border-radius: var(--plx-r);
  background: var(--plx-eink);
  box-shadow: var(--plx-recessed);
  color: var(--plx-eink-ink);
  padding: 8px 12px;
}
.Countdown_Item, .Counter__counter {
  font-family: var(--plx-mono);
  font-variant-numeric: tabular-nums;
