  border: 1px solid var(--plx-rule-soft);
  border-radius: var(--plx-r);
  background: var(--plx-plate);
  font-family: var(--plx-ui);
  overflow: hidden;
}
body:not(.plx-props-ledger, .plx-props-strip, .plx-props-margin, .plx-props-lcd, .plx-props-tucked) .metadata-container.is-collapsed { border-bottom: 1px solid var(--plx-rule-soft); }
body:not(.plx-props-ledger, .plx-props-strip, .plx-props-margin, .plx-props-lcd, .plx-props-tucked) .metadata-properties-heading {
  display: flex; align-items: center;
  min-height: 24px;
  padding: 0 !important;
  background: var(--plx-paper-2);
  border-bottom: 1px solid var(--plx-rule-soft);
}
body:not(.plx-props-ledger, .plx-props-strip, .plx-props-margin, .plx-props-lcd, .plx-props-tucked) .metadata-container.is-collapsed .metadata-properties-heading { border-bottom: 0; }
body:not(.plx-props-ledger, .plx-props-strip, .plx-props-margin, .plx-props-lcd, .plx-props-tucked) .metadata-properties-title {
  background: transparent !important;
  clip-path: none;
