}
body:not(.plx-props-ledger, .plx-props-strip, .plx-props-margin, .plx-props-lcd, .plx-props-tucked) .metadata-property:first-child { border-top: 0; }
body:not(.plx-props-ledger, .plx-props-strip, .plx-props-margin, .plx-props-lcd, .plx-props-tucked) .metadata-property-key-input {
  font-family: var(--plx-ui-cond) !important;
  font-size: 10.5px !important;
  font-style: normal;
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-kerning: none;
  color: var(--plx-ink-3) !important;
}
body:not(.plx-props-ledger, .plx-props-strip, .plx-props-margin, .plx-props-lcd, .plx-props-tucked) .metadata-property-icon { color: var(--plx-ink-4); margin-inline-end: 4px; }
body:not(.plx-props-ledger, .plx-props-strip, .plx-props-margin, .plx-props-lcd, .plx-props-tucked) :is(.metadata-property-value input:not([type="date"]):not([type="datetime-local"]):not([type="number"]), .metadata-property-value .metadata-input-longtext, .metadata-property-value .metadata-input-text:not(.mod-date):not(.mod-datetime), .multi-select-input) {
  font-family: var(--plx-ui) !important;
  font-size: 13.5px !important;
}
/* list values: boxed chips */
body:not(.plx-props-ledger, .plx-props-strip, .plx-props-margin, .plx-props-lcd, .plx-props-tucked) .multi-select-container { gap: 4px; padding: 2px 0 !important; flex-wrap: wrap; }
body:not(.plx-props-ledger, .plx-props-strip, .plx-props-margin, .plx-props-lcd, .plx-props-tucked) .multi-select-pill {
  height: 19px;
