}
body:not(.plx-props-ledger, .plx-props-strip, .plx-props-margin, .plx-props-lcd, .plx-props-tucked) .multi-select-pill:has(+ .multi-select-pill)::after { content: none !important; }
body:not(.plx-props-ledger, .plx-props-strip, .plx-props-margin, .plx-props-lcd, .plx-props-tucked) .metadata-property[data-property-key="tags"] .multi-select-pill { font-family: var(--plx-mono) !important; font-size: 11.5px !important; }
body:not(.plx-props-ledger, .plx-props-strip, .plx-props-margin, .plx-props-lcd, .plx-props-tucked) .multi-select-pill:hover { border-color: var(--plx-teal) !important; color: var(--plx-teal) !important; background: var(--plx-teal-wash) !important; }
body:not(.plx-props-ledger, .plx-props-strip, .plx-props-margin, .plx-props-lcd, .plx-props-tucked) .metadata-add-button { padding: 3px 8px !important; border-top: 1px solid var(--plx-rule-soft); width: 100%; justify-content: flex-start; }
body:not(.plx-props-ledger, .plx-props-strip, .plx-props-margin, .plx-props-lcd, .plx-props-tucked) .metadata-property-value :is(input[type="number"]) {
  font-family: var(--plx-mono) !important;
